function switchPrefTab(tab, btn) {
  document.querySelectorAll('.pref-tab').forEach(t => t.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const body = document.getElementById('pref-body');
  if (!body) return;

  // For the appearance tab, capture its HTML into _prefTabContent on first visit
  // so subsequent visits can re-render it from the string (avoids detach/re-attach bug)
  if (tab === 'appearance') {
    if (!_prefTabContent.appearance) {
      const existing = document.getElementById('pref-tab-appearance');
      if (existing) _prefTabContent.appearance = existing.outerHTML;
    }
  }

  const html = _prefTabContent[tab];
  if (html) {
    body.innerHTML = html;
  } else {
    body.innerHTML = '<div style="padding:24px;color:#94a3b8;text-align:center"><i class="fas fa-tools" style="font-size:22px;margin-bottom:8px;display:block"></i>Coming soon.</div>';
  }
}

function selectPrefTheme(theme, el) {
  document.querySelectorAll('.pref-theme-card').forEach(c => c.classList.remove('selected'));
  if (el) el.classList.add('selected');
  if (theme === 'dark') {
    showToast('Dark mode is coming in Q2 2026 — stay tuned!', 'info');
  }
}

function savePrefChanges() {
  document.getElementById('preferences-overlay')?.remove();
  showToast('<i class="fas fa-check-circle" style="margin-right:6px;color:#059669"></i>Preferences saved', 'success');
}

/* ── 7. Global keyboard shortcuts (G-sequence navigation) ────
   Press G then D/C/P/L/A for rapid page navigation.
   ─────────────────────────────────────────────────────────── */
(function initKeyboardShortcuts() {
  let _gPressed = false, _gTimer = null;
  const _gMap = { d:'dashboard', c:'clients', p:'sales', l:'calendar', a:'ai-agents',
                  r:'reports', u:'underwriting', i:'ai-insights' };
  document.addEventListener('keydown', e => {
    // Skip when typing in an input
    if (e.target.matches('input,textarea,select,[contenteditable]')) return;
    // Skip when a modal is open
    if (document.querySelector('.modal-overlay, .spotlight-overlay.open')) return;

    if (e.key === 'g' || e.key === 'G') {
      _gPressed = true;
      clearTimeout(_gTimer);
      _gTimer = setTimeout(() => { _gPressed = false; }, 1200);
      return;
    }
    if (_gPressed) {
      const page = _gMap[e.key.toLowerCase()];
      if (page) { e.preventDefault(); navigateTo(page); _gPressed = false; }
      return;
    }
    // Single-key shortcuts (no modifier)
    if (!e.metaKey && !e.ctrlKey && !e.altKey) {
      if (e.key === 'n' || e.key === 'N') toggleNotifPanel();
    }
  });
})();

