// ── STATE ─────────────────────────────────────────────────────
var _leadsCurrentFilter = 'all';
var _leadsSearchTerm = '';
var _currentLeadId = null;
var _pmailModalLeadId = null;
var _pmailStep = 1;
var _pmailAnswers = {};

// ── LEADS PAGE INIT ───────────────────────────────────────────
function initLeadsPage() {
  renderLeadsList();
  renderLeadStats();
  console.log('Leads page initialised — ' + leadsData.length + ' leads loaded');
}

function renderLeadStats() {
  var total      = leadsData.length;
  var newLeads   = leadsData.filter(function(l){ return l.status==='new'; }).length;
  var contacted  = leadsData.filter(function(l){ return l.status==='contacted'; }).length;
  var qual       = leadsData.filter(function(l){ return l.status==='qualified'; }).length;
  var inCamp     = leadsData.filter(function(l){ return l.status==='in-campaign'; }).length;
  var responded  = leadsData.filter(function(l){ return l.status==='responded'; }).length;
  var conv       = leadsData.filter(function(l){ return l.status==='converted'; }).length;

  function _set(id, val) { var el = document.getElementById(id); if(el) el.textContent = val; }
  _set('lead-stat-total',     total);
  _set('lead-stat-new',       newLeads);
  _set('lead-stat-contacted', contacted);
  _set('lead-stat-qualified', qual);
  _set('lead-stat-incampaign',inCamp);
  _set('lead-stat-responded', responded);
  _set('lead-stat-converted', conv);

  // update filter tab counts
  _set('leads-count-all',         total);
  _set('leads-count-new',         newLeads);
  _set('leads-count-contacted',   contacted);
  _set('leads-count-qualified',   qual);
  _set('leads-count-incampaign',  inCamp);
  _set('leads-count-responded',   responded);
  _set('leads-count-converted',   conv);
}

function filterLeadsByStatus(status) {
  _leadsCurrentFilter = status;
  document.querySelectorAll('.leads-filter-tab').forEach(function(t){
    t.classList.toggle('active', t.dataset.filter === status);
  });
  renderLeadsList();
}

// Status metadata helper — single source of truth
function _leadStatusMeta(status) {
  return {
    'new':         { label: 'New Lead',    cls: 'lead-status-new',         color: '#64748b' },
    'contacted':   { label: 'Contacted',   cls: 'lead-status-contacted',   color: '#0891b2' },
    'qualified':   { label: 'Qualified',   cls: 'lead-status-qualified',   color: '#d97706' },
    'in-campaign': { label: 'In Campaign', cls: 'lead-status-incampaign',  color: '#7c3aed' },
    'responded':   { label: 'Responded',   cls: 'lead-status-responded',   color: '#059669' },
    'converted':   { label: 'Converted',   cls: 'lead-status-converted',   color: '#003087' }
  }[status] || { label: status, cls: 'lead-status-new', color: '#64748b' };
}

function searchLeads(term) {
  _leadsSearchTerm = term.toLowerCase();
  renderLeadsList();
}

function renderLeadsList() {
  var container = document.getElementById('leads-list-container');
  if (!container) return;

  var filtered = leadsData.filter(function(l) {
    var matchFilter = _leadsCurrentFilter === 'all' || l.status === _leadsCurrentFilter;
    var matchSearch = !_leadsSearchTerm ||
      l.name.toLowerCase().includes(_leadsSearchTerm) ||
      l.city.toLowerCase().includes(_leadsSearchTerm) ||
      l.occupation.toLowerCase().includes(_leadsSearchTerm) ||
      l.lifeEventTrigger.toLowerCase().includes(_leadsSearchTerm);
    return matchFilter && matchSearch;
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div class="leads-empty"><i class="fas fa-search"></i><p>No leads match your filter.</p></div>';
    return;
  }

  container.innerHTML = filtered.map(function(lead) {
    var pp  = propensityProfiles[lead.id];
    var pm  = pmailScores[lead.id];
    var sm  = _leadStatusMeta(lead.status);
    var scoreColor = pp.closePct >= 80 ? '#059669' : pp.closePct >= 60 ? '#d97706' : '#dc2626';
    var sourceIcon = {
      'client-referral':'fa-users', 'linkedin':'fa-linkedin', 'seminar':'fa-chalkboard-teacher',
      'public-record':'fa-file-alt', 'life-event-alert':'fa-bell', 'event':'fa-calendar-alt',
      'campaign-linkedin':'fa-bullhorn', 'campaign-social':'fa-hashtag',
      'inbound-digital':'fa-globe', 'association-list':'fa-id-card', 'ai-scan':'fa-robot'
    }[lead.referralType] || 'fa-user';

    // Domain mini-bars
    var domBars = '';
    if (lead.domainScores) {
      var ds = lead.domainScores;
      var domLabel = ds.ins >= ds.inv && ds.ins >= ds.ret ? 'Insurance-first'
                   : ds.ret >= ds.inv ? 'Retirement-first' : 'Investment-first';
      domBars = '<div class="lead-domain-bars">' +
        '<div class="lead-domain-bar-row"><span class="ldb-lbl">INS</span><div class="ldb-track"><div class="ldb-fill ldb-ins" style="width:' + ds.ins + '%"></div></div><span class="ldb-pct">' + ds.ins + '%</span></div>' +
        '<div class="lead-domain-bar-row"><span class="ldb-lbl">INV</span><div class="ldb-track"><div class="ldb-fill ldb-inv" style="width:' + ds.inv + '%"></div></div><span class="ldb-pct">' + ds.inv + '%</span></div>' +
        '<div class="lead-domain-bar-row"><span class="ldb-lbl">RET</span><div class="ldb-track"><div class="ldb-fill ldb-ret" style="width:' + ds.ret + '%"></div></div><span class="ldb-pct">' + ds.ret + '%</span></div>' +
        '<span class="ldb-strategy">' + domLabel + '</span>' +
      '</div>';
    }

    // PMAIL dots (only if scored)
    var pmailHtml = '';
    if (pm && (lead.status === 'qualified' || lead.status === 'in-campaign' || lead.status === 'responded' || lead.status === 'converted')) {
      pmailHtml = '<div class="lead-pmail-row">' +
        ['P','M','A','I','L'].map(function(letter, i) {
          var sc = [pm.P, pm.M, pm.A, pm.I, pm.L][i];
          var cls = sc >= 5 ? 'pmail-dot-full' : sc >= 3 ? 'pmail-dot-partial' : 'pmail-dot-low';
          return '<span class="pmail-dot ' + cls + '" title="' + letter + ': ' + sc + '/5">' + letter + '</span>';
        }).join('') +
        '<span class="pmail-total" style="color:#059669">✓ ' + pm.total + '/100</span>' +
      '</div>';
    }

    // Campaign tag
    var campTag = '';
    if (lead.campaignLink) {
      var campColor = lead.campaignLink.responded ? '#059669' : '#7c3aed';
      var campIcon  = lead.campaignLink.responded ? 'fa-reply' : 'fa-bullhorn';
      campTag = '<div class="lead-camp-tag" style="color:' + campColor + '"><i class="fas ' + campIcon + '"></i> ' +
        lead.campaignLink.name.substring(0,32) + (lead.campaignLink.responded ? ' · Responded' : ' · Active') + '</div>';
    }

    // CTA button per lifecycle stage
    var actionBtn = _leadListCTA(lead);

    return '<div class="lead-card" id="lead-' + lead.id + '" onclick="selectLead(\'' + lead.id + '\')">' +
      '<div class="lead-card-top">' +
        '<div class="lead-avatar" style="background:' + lead.avatarColor + '">' + lead.initials + '</div>' +
        '<div class="lead-card-info">' +
          '<div class="lead-card-name">' + lead.name + '</div>' +
          '<div class="lead-card-occ">' + lead.occupation + '</div>' +
          '<div class="lead-card-city"><i class="fas fa-map-marker-alt"></i> ' + lead.city + '</div>' +
        '</div>' +
        '<div class="lead-card-right">' +
          '<span class="lead-status-pill ' + sm.cls + '">' + sm.label + '</span>' +
          '<div class="lead-score-badge" style="background:' + scoreColor + '">' +
            '<span class="lead-score-num">' + pp.closePct + '%</span>' +
            '<span class="lead-score-lbl">Close</span>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<div class="lead-event-strip">' +
        '<i class="fas fa-bolt lead-event-icon"></i>' +
        '<span class="lead-event-text">' + lead.lifeEventTrigger + ' — ' + lead.lifeEventDetail.substring(0,58) + (lead.lifeEventDetail.length>58?'…':'') + '</span>' +
      '</div>' +
      domBars +
      campTag +
      pmailHtml +
      '<div class="lead-card-footer">' +
        '<span class="lead-foot-date"><i class="fas fa-calendar"></i> ' + lead.entryDate + '</span>' +
        actionBtn +
      '</div>' +
    '</div>';
  }).join('');
}

function _leadListCTA(lead) {
  switch(lead.status) {
    case 'new':
      return '<button class="lead-action-btn lead-action-qualify" onclick="event.stopPropagation();openPMAILModal(\'' + lead.id + '\')"><i class="fas fa-clipboard-check"></i> Run PMAIL</button>';
    case 'contacted':
      return '<button class="lead-action-btn lead-action-qualify" onclick="event.stopPropagation();openPMAILModal(\'' + lead.id + '\')"><i class="fas fa-clipboard-check"></i> Run PMAIL</button>';
    case 'qualified':
      return '<button class="lead-action-btn lead-action-convert" onclick="event.stopPropagation();openAddToCampaignModal(\'' + lead.id + '\')"><i class="fas fa-bullhorn"></i> Add to Campaign</button>';
    case 'in-campaign':
      return '<button class="lead-action-btn lead-action-incampaign" onclick="event.stopPropagation();selectLead(\'' + lead.id + '\')"><i class="fas fa-satellite-dish"></i> Campaign Active</button>';
    case 'responded':
      return '<button class="lead-action-btn lead-action-respond" onclick="event.stopPropagation();openConvertToProspect(\'' + lead.id + '\')"><i class="fas fa-user-plus"></i> Convert to Prospect</button>';
    case 'converted':
      return '<button class="lead-action-btn lead-action-view" onclick="event.stopPropagation();openLeadHistory(\'' + lead.id + '\')"><i class="fas fa-history"></i> View Lead History</button>';
    default:
      return '';
  }
}

function selectLead(id) {
  _currentLeadId = id;
  document.querySelectorAll('.lead-card').forEach(function(c){ c.classList.remove('lead-card-active'); });
  var card = document.getElementById('lead-' + id);
  if (card) card.classList.add('lead-card-active');
  // Show detail panel, hide empty state
  var emptyState = document.getElementById('lead-detail-empty');
  var panel = document.getElementById('lead-detail-panel');
  if (emptyState) emptyState.style.display = 'none';
  if (panel) panel.style.display = 'block';
  renderLeadDetail(id);
}

function renderLeadDetail(id) {
  var panel = document.getElementById('lead-detail-panel');
  if (!panel) return;
  var emptyState = document.getElementById('lead-detail-empty');
  if (emptyState) emptyState.style.display = 'none';
  panel.style.display = 'block';
  var lead = leadsData.find(function(l){ return l.id === id; });
  if (!lead) return;
  var pp = propensityProfiles[id];
  var pm = pmailScores[id];
  var sm = _leadStatusMeta(lead.status);
  var scoreColor = pp.closePct >= 80 ? '#059669' : pp.closePct >= 60 ? '#d97706' : '#dc2626';

  // ── AI Opener box ──
  var openerHtml = pp.aiOpener
    ? '<div class="ld-opener-box"><div class="ld-opener-label"><i class="fas fa-robot"></i> AI Recommended Opening</div>' +
      '<div class="ld-opener-text">"' + pp.aiOpener + '"</div>' +
      '<button class="ld-opener-copy" onclick="navigator.clipboard&&navigator.clipboard.writeText(\'' + pp.aiOpener.replace(/'/g,"\\'") + '\');showToast(\'Opening copied to clipboard\',\'success\')"><i class="fas fa-copy"></i> Copy</button></div>'
    : '';

  // ── 3-Domain propensity bar ──
  var domHtml = '';
  if (pp.ins !== undefined) {
    var domLabel  = pp.ins >= pp.inv && pp.ins >= pp.ret ? 'Insurance-led opportunity'
                  : pp.ret >= pp.inv ? 'Retirement-led opportunity' : 'Investment-led opportunity';
    var domStrategy = pp.ins >= pp.inv && pp.ins >= pp.ret
      ? 'Lead with insurance conversation — cross-sell investments/retirement as part of holistic plan.'
      : pp.ret >= pp.inv
      ? 'Lead with retirement income conversation — insurance products as protection layer.'
      : 'Lead with investment/wealth conversation — insurance as income protection complement.';
    domHtml = '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-layer-group"></i> AI Propensity by Domain</div>' +
      '<div class="ld-domain-grid">' +
        _domainBarBlock('Insurance',   pp.ins, '#003087', 'fa-shield-alt') +
        _domainBarBlock('Investments', pp.inv, '#0891b2', 'fa-chart-line') +
        _domainBarBlock('Retirement',  pp.ret, '#7c3aed', 'fa-umbrella-beach') +
      '</div>' +
      '<div class="ld-domain-strategy"><i class="fas fa-lightbulb"></i> <strong>' + domLabel + '</strong> — ' + domStrategy + '</div>' +
    '</div>';
  }

  // ── PMAIL detail (only once scored) ──
  var pmailDetailHtml = '';
  var hasPmail = pm && (lead.status === 'qualified' || lead.status === 'in-campaign' || lead.status === 'responded' || lead.status === 'converted');
  if (hasPmail) {
    var pmItems = [
      { letter:'P', label:'Product Fit',         score:pm.P },
      { letter:'M', label:'Money / Budget',       score:pm.M },
      { letter:'A', label:'Authority',            score:pm.A },
      { letter:'I', label:'Insurability',         score:pm.I },
      { letter:'L', label:'Life Event / Urgency', score:pm.L }
    ];
    var pmColors = ['#003087','#059669','#7c3aed','#d97706','#dc2626'];
    pmailDetailHtml = '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-clipboard-check"></i> PMAIL Score — ' + pm.total + '/100' +
        '<span class="ld-pmail-qual-badge" style="background:' + (pm.total>=72?'#059669':'#d97706') + '">' + (pm.total>=80?'Strong Qualify':pm.total>=72?'Qualified':'Conditional') + '</span>' +
      '</div>' +
      '<div class="ld-pmail-compact">' +
      pmItems.map(function(item, idx) {
        var pct = (item.score/5)*100;
        var col = pmColors[idx];
        return '<div class="ld-pmail-compact-row">' +
          '<div class="ld-pmail-letter" style="background:' + col + '">' + item.letter + '</div>' +
          '<div class="ld-pmail-compact-label">' + item.label + '</div>' +
          '<div class="ld-pmail-compact-bar"><div class="ld-pmail-fill" style="width:' + pct + '%;background:' + col + '"></div></div>' +
          '<div class="ld-pmail-compact-score">' + item.score + '/5</div>' +
        '</div>';
      }).join('') +
      '</div>' +
      '<div class="ld-pmail-notes"><i class="fas fa-robot"></i> ' + pm.qualNotes + '</div>' +
    '</div>';
  }

  // ── Campaign section ──
  var campHtml = '';
  if (lead.campaignLink) {
    var cl = lead.campaignLink;
    campHtml = '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-bullhorn"></i> Campaign</div>' +
      '<div class="ld-camp-box">' +
        '<div class="ld-camp-name">' + cl.name + '</div>' +
        '<div class="ld-camp-status ' + (cl.responded ? 'ld-camp-responded' : 'ld-camp-active') + '">' +
          (cl.responded ? '<i class="fas fa-reply"></i> Responded — ' + cl.responseDate : '<i class="fas fa-satellite-dish"></i> Active — awaiting response') +
        '</div>' +
        (cl.responseNote ? '<div class="ld-camp-note">"' + cl.responseNote + '"</div>' : '') +
      '</div>' +
    '</div>';
  }

  // ── Contact log ──
  var logHtml = '';
  if (lead.contactLog && lead.contactLog.length > 0) {
    var typeIcon = { call:'fa-phone', email:'fa-envelope', linkedin:'fa-linkedin', text:'fa-sms', social:'fa-hashtag' };
    var outcomeColor = { Reached:'#059669', Replied:'#059669', Opened:'#0891b2', Sent:'#64748b', 'Left VM':'#d97706', Delivered:'#64748b', Clicked:'#0891b2' };
    logHtml = '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-history"></i> Contact Log (' + lead.contactLog.length + ')</div>' +
      '<div class="ld-contact-log">' +
      lead.contactLog.slice().reverse().map(function(entry) {
        var ic = typeIcon[entry.type] || 'fa-circle';
        var oc = outcomeColor[entry.outcome] || '#64748b';
        return '<div class="ld-log-row">' +
          '<div class="ld-log-icon" style="background:' + oc + '15;color:' + oc + '"><i class="fas ' + ic + '"></i></div>' +
          '<div class="ld-log-body">' +
            '<div class="ld-log-top"><span class="ld-log-date">' + entry.date + '</span><span class="ld-log-outcome" style="color:' + oc + '">' + entry.outcome + '</span></div>' +
            '<div class="ld-log-note">' + entry.note + '</div>' +
          '</div>' +
        '</div>';
      }).join('') +
    '</div></div>';
  }

  // ── Action buttons per lifecycle stage ──
  var actionsHtml = _leadDetailActions(lead);

  panel.innerHTML = '<div class="lead-detail-content">' +
    // Header
    '<div class="ld-header">' +
      '<div class="ld-avatar" style="background:' + lead.avatarColor + '">' + lead.initials + '</div>' +
      '<div class="ld-header-info">' +
        '<div class="ld-name">' + lead.name + '</div>' +
        '<div class="ld-occ">' + lead.occupation + '</div>' +
        '<div class="ld-location"><i class="fas fa-map-marker-alt"></i> ' + lead.city + '</div>' +
        '<span class="ld-status-badge ' + sm.cls + '">' + sm.label + '</span>' +
      '</div>' +
      '<div class="ld-score-circle" style="border-color:' + scoreColor + ';color:' + scoreColor + '">' +
        '<span class="ld-score-num">' + pp.closePct + '%</span>' +
        '<span class="ld-score-lbl">Close Prob.</span>' +
      '</div>' +
    '</div>' +
    // Contact row
    '<div class="ld-contact-row">' +
      '<a href="mailto:' + lead.email + '" class="ld-contact-btn"><i class="fas fa-envelope"></i>' + lead.email + '</a>' +
      '<a href="tel:' + lead.phone + '" class="ld-contact-btn"><i class="fas fa-phone"></i>' + lead.phone + '</a>' +
    '</div>' +
    // Life event
    '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-bolt"></i> Life Event Trigger</div>' +
      '<div class="ld-life-event-box">' +
        '<div class="ld-life-event-trigger">' + lead.lifeEventTrigger + '</div>' +
        '<div class="ld-life-event-detail">' + lead.lifeEventDetail + '</div>' +
      '</div>' +
    '</div>' +
    // AI opener
    openerHtml +
    // Domain propensity
    domHtml +
    // Propensity stats + match
    '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-brain"></i> AI Propensity — Case Match</div>' +
      '<div class="ld-propensity-box">' +
        '<div class="ld-prop-stat"><span class="ld-prop-num">' + pp.closedCasesLike + '</span><span class="ld-prop-lbl">Closed Case Matches</span></div>' +
        '<div class="ld-prop-stat"><span class="ld-prop-num" style="color:' + scoreColor + '">' + pp.closePct + '%</span><span class="ld-prop-lbl">Close Probability</span></div>' +
        '<div class="ld-prop-stat"><span class="ld-prop-num">' + pp.topProducts + '</span><span class="ld-prop-lbl">Top Product Match</span></div>' +
        '<div class="ld-prop-insight">' + pp.matchDesc + '</div>' +
      '</div>' +
    '</div>' +
    // Lead profile grid
    '<div class="ld-section">' +
      '<div class="ld-section-title"><i class="fas fa-user"></i> Lead Profile</div>' +
      '<div class="ld-grid">' +
        '<div class="ld-field"><div class="ld-field-label">Age</div><div class="ld-field-val">' + lead.age + '</div></div>' +
        '<div class="ld-field"><div class="ld-field-label">Est. Income</div><div class="ld-field-val">' + lead.estimatedIncome + '</div></div>' +
        '<div class="ld-field"><div class="ld-field-label">Source</div><div class="ld-field-val">' + lead.referralSource + '</div></div>' +
        '<div class="ld-field"><div class="ld-field-label">Entry Date</div><div class="ld-field-val">' + lead.entryDate + '</div></div>' +
        '<div class="ld-field"><div class="ld-field-label">Contacts</div><div class="ld-field-val">' + lead.contactAttempts + (lead.lastContact ? ' · Last: ' + lead.lastContact : ' · None yet') + '</div></div>' +
        '<div class="ld-field"><div class="ld-field-label">Product Interest</div><div class="ld-field-val">' + lead.productInterest.join(', ') + '</div></div>' +
      '</div>' +
    '</div>' +
    // PMAIL (if scored)
    pmailDetailHtml +
    // Campaign linkage
    campHtml +
    // Contact log
    logHtml +
    // Notes
    (lead.notes ? '<div class="ld-section"><div class="ld-section-title"><i class="fas fa-sticky-note"></i> Agent Notes</div><div class="ld-notes">' + lead.notes + '</div></div>' : '') +
    // Actions
    actionsHtml +
  '</div>';
}

function _domainBarBlock(label, pct, color, icon) {
  return '<div class="ld-domain-block">' +
    '<div class="ld-domain-block-header"><i class="fas ' + icon + '" style="color:' + color + '"></i> ' + label + '</div>' +
    '<div class="ld-domain-track"><div class="ld-domain-fill" style="width:' + pct + '%;background:' + color + '"></div></div>' +
    '<div class="ld-domain-pct" style="color:' + color + '">' + pct + '%</div>' +
  '</div>';
}

function _leadDetailActions(lead) {
  var primary = '';
  switch(lead.status) {
    case 'new':
      primary = '<button class="ld-act-btn ld-act-primary" onclick="openPMAILModal(\'' + lead.id + '\')"><i class="fas fa-clipboard-check"></i> Run PMAIL Qualification</button>';
      break;
    case 'contacted':
      primary = '<button class="ld-act-btn ld-act-primary" onclick="openPMAILModal(\'' + lead.id + '\')"><i class="fas fa-clipboard-check"></i> Run PMAIL Qualification</button>';
      break;
    case 'qualified':
      primary = '<button class="ld-act-btn ld-act-green" onclick="openAddToCampaignModal(\'' + lead.id + '\')"><i class="fas fa-bullhorn"></i> Add to Campaign</button>';
      break;
    case 'in-campaign':
      primary = '<button class="ld-act-btn ld-act-purple" onclick="showToast(\'Campaign manager coming soon\',\'info\')"><i class="fas fa-satellite-dish"></i> Manage Campaign</button>';
      break;
    case 'responded':
      primary = '<button class="ld-act-btn ld-act-green" onclick="openConvertToProspect(\'' + lead.id + '\')"><i class="fas fa-user-plus"></i> Convert to Prospect</button>';
      break;
    case 'converted':
      primary = '<button class="ld-act-btn ld-act-primary" onclick="openLeadHistory(\'' + lead.id + '\')"><i class="fas fa-history"></i> View Lead History</button>';
      break;
  }
  return '<div class="ld-actions">' +
    primary +
    '<button class="ld-act-btn ld-act-secondary" onclick="openOutreachModal(\'' + lead.id + '\')"><i class="fas fa-paper-plane"></i> Send Outreach</button>' +
    '<button class="ld-act-btn ld-act-secondary" onclick="openScheduleCallModal(\'' + lead.id + '\')"><i class="fas fa-calendar-plus"></i> Schedule Call</button>' +
  '</div>';
}

// ── PMAIL QUALIFICATION MODAL ─────────────────────────────────
var pmailQuestions = [
  {
    letter: 'P', label: 'Product Fit',
    color: '#003087',
    question: 'Is there a specific NYL product that clearly matches this prospect\'s stated need or detected gap?',
    options: [
      { score: 5, label: 'Strong match — clear primary product identified and prospect has shown interest' },
      { score: 4, label: 'Good match — product identified, prospect open but not yet expressed strong interest' },
      { score: 3, label: 'Possible match — some alignment but product mix uncertain' },
      { score: 2, label: 'Weak match — prospect needs exist but no clear product fit yet' },
      { score: 1, label: 'No clear match — prospect profile does not align with current product offerings' }
    ]
  },
  {
    letter: 'M', label: 'Money / Budget',
    color: '#059669',
    question: 'Does the prospect have the financial capacity to afford the recommended premium? Is there a budget or financial event that creates capacity?',
    options: [
      { score: 5, label: 'Budget confirmed — prospect stated willingness to pay OR clear financial event (CD maturity, IPO vesting, income increase)' },
      { score: 4, label: 'Income suggests capacity — est. income supports premium, no direct confirmation yet' },
      { score: 3, label: 'Marginal capacity — income is sufficient but tight; may require product adjustment' },
      { score: 2, label: 'Financial constraints present — student loans, high debt, or limited disposable income' },
      { score: 1, label: 'Clear financial barrier — income or debt situation makes premium unlikely affordable' }
    ]
  },
  {
    letter: 'A', label: 'Authority / Decision Maker',
    color: '#7c3aed',
    question: 'Is this prospect the primary or sole decision maker for purchasing insurance?',
    options: [
      { score: 5, label: 'Sole decision maker — confirmed single adult, business owner, or stated they make financial decisions independently' },
      { score: 4, label: 'Primary decision maker — spouse/partner exists but prospect leads financial decisions' },
      { score: 3, label: 'Joint decision — spouse/partner must be involved; both parties reasonably accessible' },
      { score: 2, label: 'Influencer, not buyer — this person influences but another party holds final authority' },
      { score: 1, label: 'Not the decision maker — prospect has explicitly deferred to another person' }
    ]
  },
  {
    letter: 'I', label: 'Insurability',
    color: '#d97706',
    question: 'Based on available data, are there likely significant health barriers that could affect insurability or rating class?',
    options: [
      { score: 5, label: 'Excellent insurability — age/profile suggests Preferred or Preferred Plus; no known health issues' },
      { score: 4, label: 'Good insurability — minor issues possible (controlled BP, weight) but Standard+ likely' },
      { score: 3, label: 'Moderate risk — some health history (diabetes controlled, past surgery); Table 2–4 possible' },
      { score: 2, label: 'Elevated risk — significant health history; rated or modified offer likely; set expectations' },
      { score: 1, label: 'High risk / likely uninsurable — recent major diagnosis, active cancer, etc.' }
    ]
  },
  {
    letter: 'L', label: 'Life Event / Urgency',
    color: '#dc2626',
    question: 'Is there a current life event or trigger that creates urgency for the prospect to act now?',
    options: [
      { score: 5, label: 'Acute event — new baby, recent home purchase, death of loved one, imminent CD maturity, IPO vesting within 90 days' },
      { score: 4, label: 'Recent event — event within 3–6 months (promotion, new business, marriage, divorce)' },
      { score: 3, label: 'Emerging trigger — event is anticipated within 12 months (planned retirement, child approaching college)' },
      { score: 2, label: 'Mild trigger — general life stage (mid-career, income growth) without specific event' },
      { score: 1, label: 'No clear trigger — prospect is stable with no identified life event driving urgency' }
    ]
  }
];

function openPMAILModal(leadId) {
  _pmailModalLeadId = leadId;
  _pmailStep = 1;
  _pmailAnswers = {};
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  if (!lead) return;

  // Build and inject the modal
  var overlay = document.createElement('div');
  overlay.id = 'pmail-overlay';
  overlay.className = 'pmail-overlay';
  overlay.innerHTML = buildPMAILModalHTML(lead);
  document.body.appendChild(overlay);
  renderPMAILStep();
}

function buildPMAILModalHTML(lead) {
  var pp = propensityProfiles[lead.id];
  return '<div class="pmail-modal">' +
    '<div class="pmail-modal-header">' +
      '<div class="pmail-modal-title-block">' +
        '<div class="pmail-modal-lead-avatar" style="background:' + lead.avatarColor + '">' + lead.initials + '</div>' +
        '<div>' +
          '<div class="pmail-modal-title">PMAIL Qualification — ' + lead.name + '</div>' +
          '<div class="pmail-modal-sub">' + lead.lifeEventTrigger + ' · ' + lead.estimatedIncome + ' · ' + lead.referralType.replace(/-/g,' ') + '</div>' +
        '</div>' +
      '</div>' +
      '<button class="pmail-modal-close" onclick="closePMAILModal()">×</button>' +
    '</div>' +
    '<div class="pmail-progress-bar">' +
      [1,2,3,4,5].map(function(i){
        return '<div class="pmail-prog-step" id="pmail-prog-' + i + '">' +
          pmailQuestions[i-1].letter +
        '</div>';
      }).join('<div class="pmail-prog-arrow">›</div>') +
    '</div>' +
    '<div class="pmail-modal-body" id="pmail-modal-body"></div>' +
    '<div class="pmail-modal-footer">' +
      '<button class="pmail-btn-back" id="pmail-btn-back" onclick="pmailBack()" style="display:none"><i class="fas fa-arrow-left"></i> Back</button>' +
      '<div class="pmail-step-indicator" id="pmail-step-indicator">Step 1 of 5</div>' +
      '<button class="pmail-btn-next" id="pmail-btn-next" onclick="pmailNext()" disabled>Next <i class="fas fa-arrow-right"></i></button>' +
    '</div>' +
  '</div>';
}

function renderPMAILStep() {
  var body = document.getElementById('pmail-modal-body');
  if (!body) return;
  var q = pmailQuestions[_pmailStep - 1];
  var lead = leadsData.find(function(l){ return l.id === _pmailModalLeadId; });
  var pp = propensityProfiles[_pmailModalLeadId];

  // Update progress dots
  for (var i = 1; i <= 5; i++) {
    var dot = document.getElementById('pmail-prog-' + i);
    if (!dot) continue;
    dot.className = 'pmail-prog-step';
    if (i < _pmailStep) dot.className += ' done';
    else if (i === _pmailStep) dot.className += ' active';
    dot.style.background = i === _pmailStep ? q.color : i < _pmailStep ? '#059669' : '#e2e8f0';
    dot.style.color = (i === _pmailStep || i < _pmailStep) ? '#fff' : '#94a3b8';
  }

  // Update step indicator
  var si = document.getElementById('pmail-step-indicator');
  if (si) si.textContent = 'Step ' + _pmailStep + ' of 5';

  // Back / Next buttons
  var back = document.getElementById('pmail-btn-back');
  var next = document.getElementById('pmail-btn-next');
  if (back) back.style.display = _pmailStep > 1 ? 'inline-flex' : 'none';
  if (next) {
    next.disabled = !_pmailAnswers[_pmailStep];
    if (_pmailStep === 5) {
      next.innerHTML = 'Calculate Score <i class="fas fa-calculator"></i>';
    } else {
      next.innerHTML = 'Next <i class="fas fa-arrow-right"></i>';
    }
  }

  // Context hint based on lead data
  var contextHint = '';
  if (_pmailStep === 1) contextHint = 'AI Detected: ' + lead.productInterest.join(', ');
  if (_pmailStep === 2) contextHint = 'AI Detected Income: ' + lead.estimatedIncome;
  if (_pmailStep === 3) contextHint = 'Source: ' + lead.referralSource;
  if (_pmailStep === 4) contextHint = 'Age: ' + lead.age + ' · Profile: ' + lead.occupation.split('—')[0];
  if (_pmailStep === 5) contextHint = 'Life Event: ' + lead.lifeEventDetail;

  body.innerHTML = '<div class="pmail-question-block">' +
    '<div class="pmail-q-header" style="border-left:4px solid ' + q.color + '">' +
      '<div class="pmail-q-letter" style="background:' + q.color + '">' + q.letter + '</div>' +
      '<div class="pmail-q-label-group">' +
        '<div class="pmail-q-label">' + q.label + '</div>' +
        '<div class="pmail-q-hint"><i class="fas fa-robot"></i> ' + contextHint + '</div>' +
      '</div>' +
    '</div>' +
    '<div class="pmail-q-text">' + q.question + '</div>' +
    '<div class="pmail-options">' +
      q.options.map(function(opt) {
        var selected = _pmailAnswers[_pmailStep] === opt.score;
        return '<div class="pmail-option ' + (selected ? 'pmail-option-selected' : '') + '" onclick="selectPMAILOption(' + opt.score + ')" style="' + (selected ? 'border-color:' + q.color + ';background:' + q.color + '10' : '') + '">' +
          '<div class="pmail-option-score" style="' + (selected ? 'background:' + q.color + ';color:#fff' : '') + '">' + opt.score + '</div>' +
          '<div class="pmail-option-label">' + opt.label + '</div>' +
        '</div>';
      }).join('') +
    '</div>' +
  '</div>';
}

function selectPMAILOption(score) {
  _pmailAnswers[_pmailStep] = score;
  var next = document.getElementById('pmail-btn-next');
  if (next) next.disabled = false;
  renderPMAILStep();
}

function pmailNext() {
  if (!_pmailAnswers[_pmailStep]) return;
  if (_pmailStep < 5) {
    _pmailStep++;
    renderPMAILStep();
  } else {
    showPMAILResult();
  }
}

function pmailBack() {
  if (_pmailStep > 1) {
    _pmailStep--;
    renderPMAILStep();
  }
}

function showPMAILResult() {
  var body = document.getElementById('pmail-modal-body');
  if (!body) return;
  var lead = leadsData.find(function(l){ return l.id === _pmailModalLeadId; });
  var pp = propensityProfiles[_pmailModalLeadId];

  var P = _pmailAnswers[1] || 0;
  var M = _pmailAnswers[2] || 0;
  var A = _pmailAnswers[3] || 0;
  var I = _pmailAnswers[4] || 0;
  var L = _pmailAnswers[5] || 0;
  var total = Math.round((P + M + A + I + L) / 25 * 100);
  var qualified = total >= 72;

  var color = total >= 80 ? '#059669' : total >= 60 ? '#d97706' : '#dc2626';
  var verdict = total >= 80 ? 'Strong Qualify' : total >= 72 ? 'Qualify' : total >= 50 ? 'Conditional' : 'Do Not Qualify';
  var verdictDesc = total >= 80 ? 'This lead is highly qualified. Move immediately to Prospect creation and schedule discovery meeting.' :
    total >= 72 ? 'Lead meets qualification threshold. Create Prospect record and begin outreach sequence.' :
    total >= 50 ? 'Lead shows potential but has qualification gaps. Address barriers before advancing.' :
    'Lead does not meet qualification criteria at this time. Nurture and re-evaluate in 90 days.';

  // Update footer buttons
  var footer = document.querySelector('.pmail-modal-footer');
  if (footer) {
    footer.innerHTML = '<button class="pmail-btn-back" onclick="pmailBackToStep5()"><i class="fas fa-arrow-left"></i> Revise</button>' +
      '<div class="pmail-step-indicator">PMAIL Score: ' + total + '/100</div>' +
      (qualified ?
        '<button class="pmail-btn-next pmail-btn-qualify" onclick="savePMAILAndQualify(' + P + ',' + M + ',' + A + ',' + I + ',' + L + ',' + total + ')"><i class="fas fa-check-circle"></i> Qualify — Add to Campaign</button>' :
        '<button class="pmail-btn-next pmail-btn-nurture" onclick="savePMAILNurture(' + total + ')"><i class="fas fa-inbox"></i> Save & Nurture</button>');
  }

  body.innerHTML = '<div class="pmail-result-block">' +
    '<div class="pmail-result-score-ring" style="border-color:' + color + '">' +
      '<div class="pmail-result-score-num" style="color:' + color + '">' + total + '</div>' +
      '<div class="pmail-result-score-label">/ 100</div>' +
    '</div>' +
    '<div class="pmail-result-verdict" style="color:' + color + '">' + verdict + '</div>' +
    '<div class="pmail-result-desc">' + verdictDesc + '</div>' +
    '<div class="pmail-result-breakdown">' +
      [['P','Product Fit',P,pmailQuestions[0].color],
       ['M','Money',M,pmailQuestions[1].color],
       ['A','Authority',A,pmailQuestions[2].color],
       ['I','Insurability',I,pmailQuestions[3].color],
       ['L','Life Event',L,pmailQuestions[4].color]].map(function(r){
        var pct = (r[2]/5)*100;
        return '<div class="pmail-result-row">' +
          '<div class="pmail-result-letter" style="background:' + r[3] + '">' + r[0] + '</div>' +
          '<div class="pmail-result-name">' + r[1] + '</div>' +
          '<div class="pmail-result-bar"><div class="pmail-result-fill" style="width:' + pct + '%;background:' + r[3] + '"></div></div>' +
          '<div class="pmail-result-score">' + r[2] + '/5</div>' +
        '</div>';
      }).join('') +
    '</div>' +
    '<div class="pmail-result-propensity">' +
      '<i class="fas fa-brain"></i> <strong>AI Propensity:</strong> This lead matches ' + pp.closedCasesLike + ' closed cases — ' + pp.matchDesc +
    '</div>' +
  '</div>';
}

function pmailBackToStep5() {
  _pmailStep = 5;
  var footer = document.querySelector('.pmail-modal-footer');
  if (footer) {
    footer.innerHTML = '<button class="pmail-btn-back" id="pmail-btn-back" onclick="pmailBack()" style="display:inline-flex"><i class="fas fa-arrow-left"></i> Back</button>' +
      '<div class="pmail-step-indicator" id="pmail-step-indicator">Step 5 of 5</div>' +
      '<button class="pmail-btn-next" id="pmail-btn-next" onclick="pmailNext()">Calculate Score <i class="fas fa-calculator"></i></button>';
  }
  renderPMAILStep();
}

function savePMAILAndQualify(P, M, A, I, L, total) {
  var lead = leadsData.find(function(l){ return l.id === _pmailModalLeadId; });
  if (!lead) return;

  // Update lead status to qualified
  lead.status = 'qualified';
  pmailScores[_pmailModalLeadId] = {
    P: P, M: M, A: A, I: I, L: L, total: total,
    qualified: true,
    qualDate: new Date().toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'}),
    qualNotes: 'PMAIL completed by agent. Score: ' + total + '/100. Moving to prospect creation.'
  };

  closePMAILModal();
  showToast('✓ ' + lead.name + ' qualified (PMAIL ' + total + '/100) — ready to add to Campaign', 'success');
  renderLeadsList();
  renderLeadStats();
  selectLead(_pmailModalLeadId);
}

function savePMAILNurture(total) {
  var lead = leadsData.find(function(l){ return l.id === _pmailModalLeadId; });
  if (!lead) return;
  closePMAILModal();
  showToast('Lead saved to nurture queue — PMAIL score: ' + total + '/100', 'info');
}

function closePMAILModal() {
  var overlay = document.getElementById('pmail-overlay');
  if (overlay) overlay.remove();
}

// ── CONVERT LEAD → PROSPECT ───────────────────────────────────
function openConvertToProspect(leadId) {
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var pm = pmailScores[leadId];
  var pp = propensityProfiles[leadId];
  var scoreColor = pp.closePct >= 80 ? '#059669' : pp.closePct >= 60 ? '#d97706' : '#dc2626';

  var overlay = document.createElement('div');
  overlay.id = 'convert-overlay';
  overlay.className = 'pmail-overlay';
  overlay.innerHTML = '<div class="convert-modal">' +
    '<div class="convert-modal-header">' +
      '<div class="convert-modal-title"><i class="fas fa-user-plus"></i> Convert to Prospect — Campaign Response Confirmed</div>' +
      '<button class="pmail-modal-close" onclick="closeConvertModal()">×</button>' +
    '</div>' +
    '<div class="convert-modal-body">' +
      '<div class="convert-lead-summary">' +
        '<div class="convert-lead-avatar" style="background:' + lead.avatarColor + '">' + lead.initials + '</div>' +
        '<div class="convert-lead-info">' +
          '<div class="convert-lead-name">' + lead.name + '</div>' +
          '<div class="convert-lead-sub">' + lead.occupation + ' · ' + lead.city + '</div>' +
          '<div class="convert-lead-event"><i class="fas fa-bolt"></i> ' + lead.lifeEventTrigger + '</div>' +
        '</div>' +
        '<div class="convert-score-badge" style="background:' + scoreColor + '">' +
          '<div class="convert-score-num">' + (pm ? pm.total : '—') + '</div>' +
          '<div class="convert-score-lbl">PMAIL</div>' +
        '</div>' +
      '</div>' +

      '<div class="convert-ai-prefill">' +
        '<div class="convert-ai-title"><i class="fas fa-robot"></i> AI Pre-filling Prospect Record…</div>' +
        '<div class="convert-prefill-list">' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> Contact info copied from lead</div>' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> PMAIL scores transferred (' + (pm ? pm.total : '—') + '/100)</div>' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> Life event trigger logged</div>' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> Propensity profile attached (' + pp.closedCasesLike + ' case matches)</div>' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> Product interest flagged: ' + lead.productInterest.join(', ') + '</div>' +
          '<div class="convert-prefill-item done"><i class="fas fa-check-circle"></i> Source attribution saved: ' + lead.referralSource + '</div>' +
          '<div class="convert-prefill-item pending"><i class="fas fa-clock"></i> 3rd-party data enrichment (D&amp;B, Experian) — scheduled</div>' +
          '<div class="convert-prefill-item pending"><i class="fas fa-clock"></i> AI strategy brief — will generate at prospect creation</div>' +
        '</div>' +
      '</div>' +

      '<div class="convert-next-actions">' +
        '<div class="convert-next-title">What happens next:</div>' +
        '<div class="convert-next-step"><span class="convert-next-num">1</span> Prospect record created in CRM with full data</div>' +
        '<div class="convert-next-step"><span class="convert-next-num">2</span> AI generates outreach recommendation and talking points</div>' +
        '<div class="convert-next-step"><span class="convert-next-num">3</span> Lead marked as converted — full history preserved and linked to Prospect</div>' +
        '<div class="convert-next-step"><span class="convert-next-num">4</span> Schedule discovery meeting → FNA Discovery to begin the sales process</div>' +
      '</div>' +
    '</div>' +
    '<div class="convert-modal-footer">' +
      '<button class="pmail-btn-back" onclick="closeConvertModal()">Cancel</button>' +
      '<button class="pmail-btn-next pmail-btn-qualify" onclick="executeConversion(\'' + leadId + '\')"><i class="fas fa-user-plus"></i> Create Prospect Record</button>' +
    '</div>' +
  '</div>';
  document.body.appendChild(overlay);
}

function executeConversion(leadId) {
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  if (!lead) return;

  // Mark lead as converted
  lead.status = 'converted';
  // Assign the matching prospect ID (L001→P001, L010→P010, etc.)
  var num = leadId.replace('L','');
  lead.prospectId = 'P' + num;

  closeConvertModal();
  showToast('✓ Prospect created — ' + lead.name + ' added to Prospects. AI brief generating…', 'success');
  renderLeadsList();
  renderLeadStats();
  selectLead(leadId);

  // Simulate a brief delay then show "view prospect" prompt
  setTimeout(function() {
    showToast('AI strategy brief ready for ' + lead.name + ' — view in Prospects', 'info');
  }, 2500);
}

function closeConvertModal() {
  var overlay = document.getElementById('convert-overlay');
  if (overlay) overlay.remove();
}

function viewLinkedProspect(prospectId) {
  if (!prospectId) return;
  navigateTo('prospects');
  setTimeout(function() {
    if (typeof openProspectModal === 'function') openProspectModal(prospectId);
  }, 300);
}

// ── SCHEDULE CALL MODAL ────────────────────────────────────────
var _schedCallLeadId = null;

function openScheduleCallModal(leadId) {
  _schedCallLeadId = leadId;
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  var pp   = propensityProfiles[leadId];
  if (!lead) return;

  var today = new Date(2026, 3, 11);
  var slotDays = [1, 2, 4];
  var slotTimes = ['9:00 AM', '11:00 AM', '2:00 PM'];
  var dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var slots = slotDays.map(function(d, i) {
    var dt = new Date(today); dt.setDate(today.getDate() + d);
    return { label: dayNames[dt.getDay()] + ' ' + monthNames[dt.getMonth()] + ' ' + dt.getDate(), time: slotTimes[i] };
  });

  var scriptLines = [
    'Hi ' + lead.name.split(' ')[0] + ', this is Sridhar from New York Life.',
    'I\'m reaching out because ' + (lead.lifeEventTrigger === 'Referral' ? 'one of my clients mentioned you' : lead.lifeEventTrigger.toLowerCase() + ' caught my attention') + '.',
    'I help people in your situation with ' + pp.topProducts + '.',
    'Do you have 15 minutes ' + slots[0].label + ' at ' + slots[0].time + '? No commitment \u2014 just a conversation.'
  ];

  var overlay = document.createElement('div');
  overlay.id = 'schedcall-overlay';
  overlay.className = 'pmail-overlay';
  overlay.onclick = function(e) { if (e.target === overlay) closeScheduleCallModal(); };
  overlay.innerHTML =
    '<div class="lm-modal">' +
      '<div class="lm-header">' +
        '<div class="lm-header-left">' +
          '<div class="lm-header-icon lm-icon-blue"><i class="fas fa-calendar-plus"></i></div>' +
          '<div>' +
            '<div class="lm-title">Schedule Call \u2014 ' + lead.name + '</div>' +
            '<div class="lm-subtitle">' + lead.occupation + ' &nbsp;&middot;&nbsp; ' + lead.city + '</div>' +
          '</div>' +
        '</div>' +
        '<button class="lm-close" onclick="closeScheduleCallModal()"><i class="fas fa-times"></i></button>' +
      '</div>' +
      '<div class="lm-body">' +
        '<div class="lm-section-label"><i class="fas fa-clock"></i> AI SUGGESTED TIMES</div>' +
        '<div class="lm-slots">' +
          slots.map(function(s, i) {
            return '<div class="lm-slot" id="sched-slot-' + i + '" onclick="selectSchedSlot(' + i + ')">' +
              '<i class="fas fa-clock lm-slot-icon"></i>' +
              '<span class="lm-slot-day">' + s.label + '</span>' +
              '<span class="lm-slot-time">' + s.time + '</span>' +
            '</div>';
          }).join('') +
          '<div class="lm-slot lm-slot-custom" id="sched-slot-3" onclick="selectSchedSlot(3)">' +
            '<i class="fas fa-pencil-alt lm-slot-icon"></i>' +
            '<span class="lm-slot-day">Custom date/time</span>' +
          '</div>' +
        '</div>' +
        '<div id="sched-custom-wrap" style="display:none;margin:6px 0 12px">' +
          '<input type="text" class="lm-text-input" id="sched-custom-input" placeholder="e.g. Apr 18 at 3:00 PM" />' +
        '</div>' +
        '<div class="lm-section-label" style="margin-top:16px"><i class="fas fa-microphone"></i> AI CALL SCRIPT</div>' +
        '<div class="lm-script-box">' +
          scriptLines.map(function(line) { return '<div class="lm-script-line">' + line + '</div>'; }).join('') +
        '</div>' +
        '<div class="lm-section-label" style="margin-top:16px"><i class="fas fa-clipboard-check"></i> LOG OUTCOME</div>' +
        '<div class="lm-chips">' +
          ['\u2192 Reached \u2014 interested','\u2192 Reached \u2014 not interested','Left Voicemail','No Answer','Rescheduled'].map(function(o) {
            var key = o.replace('\u2192 ','');
            return '<div class="lm-chip" onclick="selectSchedOutcome(this,\'' + key + '\')">' + o + '</div>';
          }).join('') +
        '</div>' +
        '<div id="sched-outcome-note-wrap" style="display:none;margin-top:8px">' +
          '<input type="text" class="lm-text-input" id="sched-outcome-note" placeholder="Optional note\u2026" />' +
        '</div>' +
      '</div>' +
      '<div class="lm-footer">' +
        '<button class="lm-btn-cancel" onclick="closeScheduleCallModal()">Cancel</button>' +
        '<button class="lm-btn-confirm" onclick="confirmScheduleCall()"><i class="fas fa-check"></i> Confirm &amp; Log</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(overlay);
}

var _schedSlotSelected = null;
var _schedOutcomeSelected = null;

function selectSchedSlot(idx) {
  _schedSlotSelected = idx;
  document.querySelectorAll('.lm-slot').forEach(function(el, i) { el.classList.toggle('lm-slot-active', i === idx); });
  var custom = document.getElementById('sched-custom-wrap');
  if (custom) custom.style.display = idx === 3 ? 'block' : 'none';
}

function selectSchedOutcome(el, outcome) {
  _schedOutcomeSelected = outcome;
  document.querySelectorAll('.lm-chip').forEach(function(c){ c.classList.remove('lm-chip-active'); });
  el.classList.add('lm-chip-active');
  var noteWrap = document.getElementById('sched-outcome-note-wrap');
  if (noteWrap) noteWrap.style.display = 'block';
}

function confirmScheduleCall() {
  var lead = leadsData.find(function(l){ return l.id === _schedCallLeadId; });
  if (!lead) return;

  var slotLabels = ['Mon Apr 13 · 9:00 AM','Tue Apr 14 · 11:00 AM','Thu Apr 16 · 2:00 PM','Custom'];
  var slotLabel  = _schedSlotSelected !== null ? slotLabels[_schedSlotSelected] || 'Custom' : 'Unspecified';
  var outcome    = _schedOutcomeSelected || 'Scheduled';
  var note       = (document.getElementById('sched-outcome-note') || {}).value || '';

  // Log contact attempt
  if (!lead.contactLog) lead.contactLog = [];
  lead.contactLog.push({ date: 'Apr 11, 2026', type: 'call', outcome: outcome, note: slotLabel + (note ? ' — ' + note : '') });
  lead.contactAttempts = (lead.contactAttempts || 0) + 1;
  lead.lastContact = 'Apr 11, 2026';

  // Advance status: new → contacted
  if (lead.status === 'new') lead.status = 'contacted';

  closeScheduleCallModal();
  showToast('<i class="fas fa-calendar-check"></i> Call scheduled — ' + slotLabel + ' · Outcome: ' + outcome, 'success');
  renderLeadsList();
  renderLeadStats();
  selectLead(_schedCallLeadId);
}

function closeScheduleCallModal() {
  var el = document.getElementById('schedcall-overlay');
  if (el) el.remove();
  _schedSlotSelected = null;
  _schedOutcomeSelected = null;
}

// ── OUTREACH MODAL (Leads) ──────────────────────────────────────
// NOTE: openOutreachModal is already defined as a router shim above.
// This function handles lead-specific IDs (non-OR-*) via that shim.
var _outreachLeadId = null;

function _openLeadsOutreachModal(leadId) {
  _outreachLeadId = leadId;
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  var pp   = propensityProfiles[leadId];
  if (!lead) return;

  var channelMap = {
    'linkedin':'LinkedIn', 'campaign-linkedin':'LinkedIn', 'inbound-digital':'Email',
    'client-referral':'Email', 'seminar':'Email', 'public-record':'Email',
    'life-event-alert':'Email', 'event':'Email', 'campaign-social':'Text',
    'association-list':'Email', 'ai-scan':'Email'
  };
  var defaultChannel = channelMap[lead.referralType] || 'Email';
  var sourceLabel = lead.referralType.replace(/-/g,' ');
  var draft = pp.aiOpener || ('Hi ' + lead.name.split(' ')[0] + ' \u2014 ' + pp.topProducts + ' looks like a strong fit based on your recent ' + lead.lifeEventTrigger + '. Worth a quick conversation?');
  var channels = ['Email','Text','LinkedIn','Phone','Direct Mail'];

  var overlay = document.createElement('div');
  overlay.id = 'outreach-overlay';
  overlay.className = 'pmail-overlay';
  overlay.onclick = function(e) { if (e.target === overlay) closeOutreachModal(); };
  overlay.innerHTML =
    '<div class="lm-modal">' +
      '<div class="lm-header">' +
        '<div class="lm-header-left">' +
          '<div class="lm-header-icon lm-icon-teal"><i class="fas fa-paper-plane"></i></div>' +
          '<div>' +
            '<div class="lm-title">Send Outreach \u2014 ' + lead.name + '</div>' +
            '<div class="lm-subtitle">' + lead.occupation + ' &nbsp;&middot;&nbsp; ' + lead.city + '</div>' +
          '</div>' +
        '</div>' +
        '<button class="lm-close" onclick="closeOutreachModal()"><i class="fas fa-times"></i></button>' +
      '</div>' +
      '<div class="lm-body">' +
        '<div class="lm-channel-rec"><i class="fas fa-robot"></i> AI RECOMMENDED CHANNEL: <strong>' + defaultChannel.toUpperCase() + '</strong> <span class="lm-channel-rec-src">(based on source: ' + sourceLabel + ')</span></div>' +
        '<div class="lm-ch-row">' +
          channels.map(function(ch) {
            return '<div class="lm-ch-chip ' + (ch === defaultChannel ? 'lm-ch-active' : '') + '" onclick="selectOutreachChannel(this,\'' + ch + '\')">' + ch + '</div>';
          }).join('') +
        '</div>' +
        '<div class="lm-section-label" style="margin-top:14px"><i class="fas fa-robot"></i> AI-DRAFTED MESSAGE</div>' +
        '<textarea class="lm-draft-area" id="outreach-draft-text">' + draft + '</textarea>' +
        '<div class="lm-draft-hint">Personalised to life event trigger &nbsp;&middot;&nbsp; Edit freely before sending</div>' +
        '<div class="lm-section-label" style="margin-top:12px"><i class="fas fa-info-circle"></i> CONTEXT</div>' +
        '<div class="lm-ctx-pills">' +
          '<span class="lm-ctx-pill"><i class="fas fa-bolt"></i> ' + lead.lifeEventTrigger + '</span>' +
          '<span class="lm-ctx-pill"><i class="fas fa-dollar-sign"></i> ' + lead.estimatedIncome + '</span>' +
          '<span class="lm-ctx-pill"><i class="fas fa-tag"></i> ' + lead.productInterest[0] + '</span>' +
        '</div>' +
      '</div>' +
      '<div class="lm-footer">' +
        '<button class="lm-btn-cancel" onclick="closeOutreachModal()">Cancel</button>' +
        '<button class="lm-btn-confirm lm-btn-teal" onclick="confirmOutreach()"><i class="fas fa-paper-plane"></i> Send &amp; Log</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(overlay);
}

var _outreachChannelSelected = null;

function selectOutreachChannel(el, channel) {
  _outreachChannelSelected = channel;
  document.querySelectorAll('.lm-ch-chip').forEach(function(c){ c.classList.remove('lm-ch-active'); });
  el.classList.add('lm-ch-active');
}

function confirmOutreach() {
  var lead = leadsData.find(function(l){ return l.id === _outreachLeadId; });
  if (!lead) return;
  var channel  = _outreachChannelSelected || 'Email';
  var draftEl  = document.getElementById('outreach-draft-text');
  var msgSnip  = draftEl ? draftEl.value.substring(0,60) + (draftEl.value.length>60?'…':'') : '';

  if (!lead.contactLog) lead.contactLog = [];
  lead.contactLog.push({ date: 'Apr 11, 2026', type: channel.toLowerCase(), outcome: 'Sent', note: channel + ' outreach sent: "' + msgSnip + '"' });
  lead.contactAttempts = (lead.contactAttempts || 0) + 1;
  lead.lastContact = 'Apr 11, 2026';
  if (lead.status === 'new') lead.status = 'contacted';

  closeOutreachModal();
  showToast('<i class="fas fa-paper-plane"></i> ' + channel + ' outreach sent to ' + lead.name + ' — contact logged', 'success');
  renderLeadsList();
  renderLeadStats();
  selectLead(_outreachLeadId);
}

function closeOutreachModal() {
  var el = document.getElementById('outreach-overlay');
  if (el) el.remove();
  _outreachChannelSelected = null;
}

// ── ADD TO CAMPAIGN MODAL ──────────────────────────────────────
function openAddToCampaignModal(leadId) {
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  var pp   = propensityProfiles[leadId];
  if (!lead) return;

  // Pick relevant campaigns based on domain scores
  var relevantCamps = campaignData.filter(function(c){ return c.status === 'active'; });

  var overlay = document.createElement('div');
  overlay.id   = 'addcamp-overlay';
  overlay.className = 'pmail-overlay';
  overlay.onclick = function(e) { if (e.target === overlay) closeAddToCampaignModal(); };
  overlay.innerHTML =
    '<div class="sched-modal">' +
      '<div class="sched-modal-header">' +
        '<div class="sched-modal-title"><i class="fas fa-bullhorn"></i> Add to Campaign — ' + lead.name + '</div>' +
        '<button class="pmail-modal-close" onclick="closeAddToCampaignModal()">×</button>' +
      '</div>' +
      '<div class="sched-modal-body">' +
        '<div class="addcamp-lead-summary">' +
          '<div class="lead-avatar" style="background:' + lead.avatarColor + ';width:36px;height:36px;font-size:0.85rem">' + lead.initials + '</div>' +
          '<div><div class="addcamp-lead-name">' + lead.name + '</div>' +
          '<div class="addcamp-lead-sub"><i class="fas fa-brain"></i> ' + pp.topProducts + ' · PMAIL ' + (pmailScores[leadId] ? pmailScores[leadId].total : '—') + '/100</div></div>' +
        '</div>' +
        '<div class="sched-section-label"><i class="fas fa-robot"></i> AI-Recommended Campaigns</div>' +
        '<div class="addcamp-list">' +
          relevantCamps.map(function(camp) {
            var match = camp.targetLeads && camp.targetLeads.includes(leadId);
            return '<div class="addcamp-row ' + (match?'addcamp-row-match':'') + '" onclick="selectCampaignForLead(\'' + camp.id + '\',this)">' +
              '<div class="addcamp-row-left">' +
                '<div class="addcamp-camp-icon" style="background:' + camp.statusColor + '22;color:' + camp.statusColor + '"><i class="fas ' + camp.typeIcon + '"></i></div>' +
                '<div>' +
                  '<div class="addcamp-camp-name">' + camp.name + (match?' <span class="addcamp-match-tag">Best match</span>':'') + '</div>' +
                  '<div class="addcamp-camp-sub">' + camp.targetSegment + '</div>' +
                  '<div class="addcamp-camp-stats"><i class="fas fa-percentage"></i> ' + camp.responseRate + '% response · ' + camp.channel + '</div>' +
                '</div>' +
              '</div>' +
              '<div class="addcamp-row-check" id="addcamp-check-' + camp.id + '"><i class="fas fa-circle"></i></div>' +
            '</div>';
          }).join('') +
        '</div>' +
      '</div>' +
      '<div class="sched-modal-footer">' +
        '<button class="pmail-btn-back" onclick="closeAddToCampaignModal()">Cancel</button>' +
        '<button class="pmail-btn-next pmail-btn-qualify" onclick="confirmAddToCampaign(\'' + leadId + '\')"><i class="fas fa-plus-circle"></i> Add to Campaign</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(overlay);
}

var _selectedCampaignId = null;

function selectCampaignForLead(campId, el) {
  _selectedCampaignId = campId;
  document.querySelectorAll('.addcamp-row').forEach(function(r){ r.classList.remove('addcamp-row-selected'); });
  document.querySelectorAll('.addcamp-row-check').forEach(function(c){ c.innerHTML = '<i class="fas fa-circle"></i>'; });
  el.classList.add('addcamp-row-selected');
  var check = document.getElementById('addcamp-check-' + campId);
  if (check) check.innerHTML = '<i class="fas fa-check-circle" style="color:#059669"></i>';
}

function confirmAddToCampaign(leadId) {
  if (!_selectedCampaignId) { showToast('Please select a campaign first', 'info'); return; }
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  var camp = campaignData.find(function(c){ return c.id === _selectedCampaignId; });
  if (!lead || !camp) return;

  lead.status = 'in-campaign';
  lead.campaignLink = { id: camp.id, name: camp.name, responded: false, responseDate: null, responseNote: null };
  if (!lead.contactLog) lead.contactLog = [];
  lead.contactLog.push({ date: 'Apr 11, 2026', type: 'email', outcome: 'Sent', note: 'Added to campaign: ' + camp.name + ' — first message queued' });
  lead.contactAttempts = (lead.contactAttempts || 0) + 1;
  lead.lastContact = 'Apr 11, 2026';

  closeAddToCampaignModal();
  showToast('<i class="fas fa-bullhorn"></i> ' + lead.name + ' added to "' + camp.name + '" — first message queued', 'success');
  renderLeadsList();
  renderLeadStats();
  selectLead(leadId);
}

function closeAddToCampaignModal() {
  var el = document.getElementById('addcamp-overlay');
  if (el) el.remove();
  _selectedCampaignId = null;
}

// ── LEAD HISTORY MODAL (converted leads) ──────────────────────
function openLeadHistory(leadId) {
  var lead = leadsData.find(function(l){ return l.id === leadId; });
  var pm   = pmailScores[leadId];
  var pp   = propensityProfiles[leadId];
  if (!lead) return;

  var typeIconMap  = { call:'fa-phone', email:'fa-envelope', linkedin:'fa-linkedin', text:'fa-comment-alt', social:'fa-hashtag', campaign:'fa-bullhorn', pmail:'fa-clipboard-check' };
  var outcomeColorMap = { Reached:'#059669', Replied:'#059669', Opened:'#0891b2', Sent:'#64748b', 'Left VM':'#d97706', Delivered:'#64748b', Clicked:'#0891b2', Scheduled:'#003087' };

  var logRows = (lead.contactLog || []).map(function(entry) {
    var ic  = typeIconMap[entry.type]  || 'fa-circle';
    var oc  = outcomeColorMap[entry.outcome] || '#64748b';
    var positiveOutcomes = ['Reached','Replied','Opened','Clicked','Scheduled'];
    var neutralOutcomes  = ['Left VM','Sent','Delivered'];
    var ocCls = positiveOutcomes.indexOf(entry.outcome) > -1 ? 'positive' : neutralOutcomes.indexOf(entry.outcome) > -1 ? 'neutral' : 'pending';
    return '<div class="lh-timeline-row">' +
      '<div class="lh-tl-icon" style="background:' + oc + '18;color:' + oc + '"><i class="fas ' + ic + '"></i></div>' +
      '<div class="lh-tl-body">' +
        '<div class="lh-tl-top">' +
          '<span class="lh-tl-date">' + entry.date + '</span>' +
          '<span class="lh-tl-outcome ld-log-outcome ' + ocCls + '">' + entry.outcome + '</span>' +
        '</div>' +
        '<div class="lh-tl-note">' + entry.note + '</div>' +
      '</div>' +
    '</div>';
  }).join('') || '<div class="lh-empty">No contact history recorded.</div>';

  var pmailStr = pm ? pm.total + '/100 &nbsp;&middot;&nbsp; ' + pm.qualDate : '\u2014';
  var campStr  = lead.campaignLink ? lead.campaignLink.name : '\u2014';
  var respStr  = (lead.campaignLink && lead.campaignLink.responded)
    ? lead.campaignLink.responseDate + ' \u2014 ' + (lead.campaignLink.responseNote || '')
    : 'No response recorded';

  var overlay = document.createElement('div');
  overlay.id = 'leadhist-overlay';
  overlay.className = 'pmail-overlay';
  overlay.onclick = function(e) { if (e.target === overlay) closeLeadHistory(); };
  overlay.innerHTML =
    '<div class="lm-modal lm-modal-hist">' +
      '<div class="lm-header">' +
        '<div class="lm-header-left">' +
          '<div class="lm-header-icon lm-icon-navy"><i class="fas fa-history"></i></div>' +
          '<div>' +
            '<div class="lm-title">Lead History</div>' +
            '<div class="lm-subtitle">' + lead.name + ' &nbsp;&middot;&nbsp; ' + lead.id + '</div>' +
          '</div>' +
        '</div>' +
        '<button class="lm-close" onclick="closeLeadHistory()"><i class="fas fa-times"></i></button>' +
      '</div>' +
      '<div class="lm-body">' +
        '<div class="lh-info-grid">' +
          '<div class="lh-info-card"><div class="lh-info-lbl">LEAD ID</div><div class="lh-info-val">' + lead.id + '</div></div>' +
          '<div class="lh-info-card"><div class="lh-info-lbl">ENTRY DATE</div><div class="lh-info-val">' + lead.entryDate + '</div></div>' +
          '<div class="lh-info-card lh-info-wide"><div class="lh-info-lbl">SOURCE</div><div class="lh-info-val">' + lead.referralSource + '</div></div>' +
          '<div class="lh-info-card"><div class="lh-info-lbl">LIFE EVENT</div><div class="lh-info-val">' + lead.lifeEventTrigger + '</div></div>' +
          '<div class="lh-info-card"><div class="lh-info-lbl">PMAIL SCORE</div><div class="lh-info-val">' + pmailStr + '</div></div>' +
          '<div class="lh-info-card lh-info-wide"><div class="lh-info-lbl">CAMPAIGN</div><div class="lh-info-val">' + campStr + '</div></div>' +
          '<div class="lh-info-card lh-info-full"><div class="lh-info-lbl">RESPONSE</div><div class="lh-info-val">' + respStr + '</div></div>' +
          '<div class="lh-info-card lh-info-full"><div class="lh-info-lbl">PROSPECT ID</div><div class="lh-info-val">' +
            (lead.prospectId ? '<a href="#" onclick="closeLeadHistory();viewLinkedProspect(\'' + lead.prospectId + '\');return false" class="lh-prospect-link">' + lead.prospectId + ' <i class="fas fa-arrow-right"></i></a>' : '\u2014') +
          '</div></div>' +
        '</div>' +
        '<div class="lm-section-label" style="margin-top:16px"><i class="fas fa-history"></i> CONTACT TIMELINE</div>' +
        '<div class="lh-timeline">' + logRows + '</div>' +
      '</div>' +
      '<div class="lm-footer">' +
        '<button class="lm-btn-cancel" onclick="closeLeadHistory()">Close</button>' +
        (lead.prospectId ? '<button class="lm-btn-confirm" onclick="closeLeadHistory();viewLinkedProspect(\'' + lead.prospectId + '\')"><i class="fas fa-user"></i> Open Prospect Record</button>' : '') +
      '</div>' +
    '</div>';
  document.body.appendChild(overlay);
}

function closeLeadHistory() {
  var el = document.getElementById('leadhist-overlay');
  if (el) el.remove();
}

// ── CAMPAIGNS PAGE ────────────────────────────────────────────
function initCampaignsPage() {
  renderCampaignGrid();
  renderCampaignStats();
  console.log('Campaigns page (Phase 1) initialised — ' + campaignData.length + ' campaigns');
}

function renderCampaignStats() {
  var active    = campaignData.filter(function(c){ return c.status==='active'; }).length;
  var totalResp = campaignData.reduce(function(s,c){ return s+c.responded; }, 0);
  var totalMtgs = campaignData.reduce(function(s,c){ return s+c.meetingsBooked; }, 0);
  var avgRate   = Math.round(campaignData.reduce(function(s,c){ return s+c.responseRate; },0)/campaignData.length);

  var sa = document.getElementById('camp-stat-active');      if(sa) sa.textContent = active;
  var sr = document.getElementById('camp-stat-responses');   if(sr) sr.textContent = totalResp;
  var sm = document.getElementById('camp-stat-meetings');    if(sm) sm.textContent = totalMtgs;
  var sg = document.getElementById('camp-stat-rate');        if(sg) sg.textContent = avgRate + '%';
}

function renderCampaignGrid() {
  var container = document.getElementById('campaigns-grid-container');
  if (!container) return;

  container.innerHTML = campaignData.map(function(camp) {
    var respPct = camp.responseRate;
    var convPct = camp.conversionRate;
    var statusBadge = camp.status === 'active'
      ? '<span class="camp-status-live"><i class="fas fa-circle"></i> LIVE</span>'
      : '<span class="camp-status-done">Completed</span>';

    var respondedHtml = camp.respondedLeads.map(function(r) {
      var lead = leadsData.find(function(l){ return l.id === r.id; });
      var initials = lead ? lead.initials : r.name.split(' ').map(function(w){ return w[0]; }).join('');
      var color = lead ? lead.avatarColor : '#64748b';
      return '<div class="camp-resp-item">' +
        '<div class="camp-resp-avatar" style="background:' + color + '">' + initials + '</div>' +
        '<div class="camp-resp-info">' +
          '<div class="camp-resp-name">' + r.name + '</div>' +
          '<div class="camp-resp-detail">' + r.response.substring(0,55) + (r.response.length>55?'…':'') + '</div>' +
          '<div class="camp-resp-stage"><i class="fas fa-arrow-right"></i> ' + r.stage + '</div>' +
        '</div>' +
      '</div>';
    }).join('');

    var msgHtml = camp.messages.map(function(msg) {
      return '<div class="camp-msg-item">' +
        '<span class="camp-msg-seq">Seq ' + msg.seq + '</span>' +
        '<span class="camp-msg-channel camp-ch-' + msg.channel.toLowerCase().replace(/[^a-z]/g,'') + '">' + msg.channel + '</span>' +
        '<span class="camp-msg-day">Day ' + msg.day + '</span>' +
        '<span class="camp-msg-subject">' + msg.subject.substring(0,45) + (msg.subject.length>45?'…':'') + '</span>' +
        '<span class="camp-msg-open">' + msg.openRate + '% open</span>' +
      '</div>';
    }).join('');

    return '<div class="camp-card" id="camp-' + camp.id + '">' +
      '<div class="camp-card-header">' +
        '<div class="camp-card-left">' +
          '<div class="camp-type-icon" style="background:' + camp.statusColor + '15;color:' + camp.statusColor + '"><i class="fas ' + camp.typeIcon + '"></i></div>' +
          '<div>' +
            '<div class="camp-card-name">' + camp.name + '</div>' +
            '<div class="camp-card-type">' + camp.type + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="camp-card-right">' +
          statusBadge +
          '<div class="camp-date-range">' + camp.startDate + ' – ' + camp.endDate + '</div>' +
        '</div>' +
      '</div>' +

      '<div class="camp-qualifier-box">' +
        '<i class="fas fa-filter"></i> <strong>Qualifier:</strong> ' + camp.qualifier +
      '</div>' +

      '<div class="camp-metrics-row">' +
        '<div class="camp-metric">' +
          '<div class="camp-metric-val">' + camp.totalTargeted + '</div>' +
          '<div class="camp-metric-lbl">Targeted</div>' +
        '</div>' +
        '<div class="camp-metric">' +
          '<div class="camp-metric-val">' + camp.opened + '</div>' +
          '<div class="camp-metric-lbl">Opened</div>' +
        '</div>' +
        '<div class="camp-metric camp-metric-highlight">' +
          '<div class="camp-metric-val" style="color:#003087">' + camp.responded + '</div>' +
          '<div class="camp-metric-lbl">Responded</div>' +
        '</div>' +
        '<div class="camp-metric">' +
          '<div class="camp-metric-val">' + camp.meetingsBooked + '</div>' +
          '<div class="camp-metric-lbl">Meetings</div>' +
        '</div>' +
        '<div class="camp-metric">' +
          '<div class="camp-metric-val" style="color:#059669">' + camp.converted + '</div>' +
          '<div class="camp-metric-lbl">Converted</div>' +
        '</div>' +
      '</div>' +

      '<div class="camp-rate-bars">' +
        '<div class="camp-rate-row">' +
          '<span class="camp-rate-label">Response Rate</span>' +
          '<div class="camp-rate-bar"><div class="camp-rate-fill" style="width:' + respPct + '%;background:#003087"></div></div>' +
          '<span class="camp-rate-pct">' + respPct + '%</span>' +
        '</div>' +
        '<div class="camp-rate-row">' +
          '<span class="camp-rate-label">Conversion Rate</span>' +
          '<div class="camp-rate-bar"><div class="camp-rate-fill" style="width:' + Math.min(convPct*3,100) + '%;background:#059669"></div></div>' +
          '<span class="camp-rate-pct">' + convPct + '%</span>' +
        '</div>' +
      '</div>' +

      '<div class="camp-section-title"><i class="fas fa-users"></i> Responded Prospects</div>' +
      '<div class="camp-resp-list">' + respondedHtml + '</div>' +

      '<div class="camp-section-title"><i class="fas fa-envelope-open"></i> Message Sequence</div>' +
      '<div class="camp-msg-list">' + msgHtml + '</div>' +

      '<div class="camp-ai-insight"><i class="fas fa-lightbulb"></i> <strong>AI Insight:</strong> ' + camp.aiInsight + '</div>' +

      '<div class="camp-revenue-row">' +
        '<span class="camp-revenue-item"><i class="fas fa-dollar-sign"></i> Expected Revenue: <strong>' + camp.expectedRevenue + '</strong></span>' +
        '<span class="camp-revenue-item"><i class="fas fa-coins"></i> Expected Commission: <strong>' + camp.expectedCommission + '</strong></span>' +
      '</div>' +

      '<div class="camp-card-actions">' +
        '<button class="camp-act-btn camp-act-primary" onclick="viewCampaignProspects(\'' + camp.id + '\')"><i class="fas fa-users"></i> View Prospects</button>' +
        (camp.status === 'active' ? '<button class="camp-act-btn camp-act-secondary" onclick="openNewCampaignModal()"><i class="fas fa-plus"></i> New Campaign</button>' : '') +
        '<button class="camp-act-btn camp-act-secondary" onclick="openCampAIWizard()"><i class="fas fa-robot"></i> AI Wizard</button>' +
      '</div>' +
    '</div>';
  }).join('');
}

function viewCampaignProspects(campId) {
  var camp = campaignData.find(function(c){ return c.id === campId; });
  if (!camp) return;
  showToast('Showing ' + camp.respondedLeads.length + ' responded prospects for "' + camp.name + '"', 'info');
}

