function p7ChangeStatus(claimId, newStatus) {
  var statusColors = { 'Under Review':'#0891b2','Pending Docs':'#d97706','Approved':'#059669','Denied':'#dc2626','On Hold':'#7c3aed' };
  var sc = statusColors[newStatus] || '#64748b';
  p7Toast('<i class="fas fa-exchange-alt"></i> ' + claimId + ' status changed to <strong style="color:' + sc + '">' + newStatus + '</strong> — workflow updated', 3500);
}

function p7AddNote(claimId) {
  var text = (document.getElementById('p7cm-note-text') || {}).value || '';
  var type = (document.getElementById('p7cm-note-type') || {}).value || 'Adjuster Note';
  if (!text.trim()) { p7Toast('Please enter a note before saving', 2000); return; }
  p7Toast('<i class="fas fa-check-circle"></i> ' + type + ' saved for ' + claimId + ' — audit trail updated', 3000);
  var el = document.getElementById('p7cm-note-text');
  if (el) el.value = '';
}

function p7AddTimelineEvent(claimId) {
  var text = (document.getElementById('p7cm-tl-event') || {}).value || '';
  if (!text.trim()) { p7Toast('Please enter an event description', 2000); return; }
  var today = new Date();
  var label = 'Apr ' + today.getDate();
  p7Toast('<i class="fas fa-stream"></i> Timeline event added: ' + text.substring(0,50), 3000);
  var el = document.getElementById('p7cm-tl-event');
  if (el) el.value = '';
}

function p7LogCall(claimId) { openLogCallModal(claimId); }
function p7SendClaimEmail(claimId) { p7Toast('<i class="fas fa-envelope"></i> Email composer opened for ' + claimId, 2500); }
function p7AddCommLog(claimId) {
  var type = (document.getElementById('p7cm-comm-type') || {}).value || 'Phone';
  var dir = (document.getElementById('p7cm-comm-dir') || {}).value || 'Outbound';
  var note = (document.getElementById('p7cm-comm-note') || {}).value || '';
  if (!note.trim()) { p7Toast('Please enter a note before adding', 2000); return; }
  p7Toast('<i class="fas fa-check-circle"></i> Communication logged: ' + type + ' — ' + note.substring(0,40) + '…', 3000);
}

function p7CloseClaimModal() {
  var overlay = document.getElementById('p7-claim-modal-overlay');
  if (overlay) overlay.remove();
}

function p7ApproveClaim(claimId) {
  p7Toast('<i class="fas fa-check-circle"></i> Claim ' + claimId + ' approved — payment processing initiated', 4000);
  p7CloseClaimModal();
}

function p7DenyClaim(claimId) {
  p7Toast('<i class="fas fa-times-circle"></i> Claim ' + claimId + ' denial initiated — adverse action letter required (ADA compliance)', 4000);
  p7CloseClaimModal();
}

function p7OpenFraudDetail(claimId) {
  p7Toast('<i class="fas fa-shield-virus"></i> Opening full fraud investigation file for ' + claimId + '…', 2500);
}

function p7RequestDoc(claimId, docName) {
  p7Toast('<i class="fas fa-paper-plane"></i> Document request sent for: ' + docName + ' — tracking added to claim timeline', 3000);
}

function p7ViewDoc(docName) {
  p7Toast('<i class="fas fa-file-alt"></i> Opening: ' + docName, 2000);
}

function p7SendAllDocRequests(claimId) {
  p7Toast('<i class="fas fa-paper-plane"></i> All missing document requests sent for ' + claimId + ' — AI-drafted letters generated', 3000);
}

function p7AddTimelineNote(claimId) {
  var input = document.getElementById('p7cm-tl-note');
  var note = input ? input.value.trim() : '';
  if (!note) { p7Toast('<i class="fas fa-exclamation-circle"></i> Please enter a note', 2000); return; }
  p7Toast('<i class="fas fa-check-circle"></i> Timeline note added to ' + claimId, 2000);
  if (input) input.value = '';
}

