var iaDriftAccounts = iaAccounts.filter(function(a) { return a.driftAlert; });

/* ═══════════════════════════════════════════════════════════════════
   TLH DATA — accounts with tax-loss harvesting opportunities
   ═══════════════════════════════════════════════════════════════════ */
