/* ═══════════════════════════════════════════════════════════════════
   STATE
   ═══════════════════════════════════════════════════════════════════ */
var _iaActiveAccount = null;
var _iaActiveTab     = 'overview';
var _iaFilterType    = '';
var _iaFilterStatus  = '';
var _iaSearchTerm    = '';

/* ═══════════════════════════════════════════════════════════════════
   INIT
   ═══════════════════════════════════════════════════════════════════ */
function initInvAccountsPage() {
  requestAnimationFrame(function() {
    setTimeout(function() {
      iaRenderAccountQueue();
    }, 80);
  });
}

/* ═══════════════════════════════════════════════════════════════════
   ACCOUNT QUEUE RENDERER
   ═══════════════════════════════════════════════════════════════════ */
function iaRenderAccountQueue() {
  var queue = document.getElementById('ia-account-queue');
  if (!queue) return;

  var accounts = iaGetFilteredAccounts();

  // Group by status priority
  var funding  = accounts.filter(function(a) { return a.status === 'Funding Pending'; });
  var review   = accounts.filter(function(a) { return a.status === 'Review Due'; });
  var drift    = accounts.filter(function(a) { return a.status === 'Active' && a.driftAlert; });
  var active   = accounts.filter(function(a) { return a.status === 'Active' && !a.driftAlert; });

  var html = '';

  if (funding.length) {
    html += '<div class="ia-section-hdr ia-section-funding"><i class="fas fa-hourglass-half"></i> Funding Pending <span class="ia-sec-count">' + funding.length + '</span></div>';
    html += funding.map(iaRenderAccountCard).join('');
  }
  if (review.length) {
    html += '<div class="ia-section-hdr ia-section-review"><i class="fas fa-exclamation-circle"></i> Review Due <span class="ia-sec-count">' + review.length + '</span></div>';
    html += review.map(iaRenderAccountCard).join('');
  }
  if (drift.length) {
    html += '<div class="ia-section-hdr ia-section-drift"><i class="fas fa-balance-scale"></i> Drift Alert <span class="ia-sec-count">' + drift.length + '</span></div>';
    html += drift.map(iaRenderAccountCard).join('');
  }
  if (active.length) {
    html += '<div class="ia-section-hdr ia-section-active"><i class="fas fa-check-circle"></i> Active — On Target <span class="ia-sec-count">' + active.length + '</span></div>';
    html += active.map(iaRenderAccountCard).join('');
  }
  if (!accounts.length) {
    html = '<div class="ia-empty-state"><i class="fas fa-search"></i><span>No accounts match your filters</span></div>';
  }

  queue.innerHTML = html;
}

function iaGetFilteredAccounts() {
  var annuitySubTypeFilters = ['Fixed deferred annuities','Variable annuities','Hybrid variable annuities'];
  return iaAccounts.filter(function(a) {
    var typeMatch;
    if (!_iaFilterType) {
      typeMatch = true;
    } else if (annuitySubTypeFilters.indexOf(_iaFilterType) >= 0) {
      // Filter by annuity sub-type
      typeMatch = a.accountType === 'Annuities' && a.annuitySubType === _iaFilterType;
    } else {
      typeMatch = a.accountType === _iaFilterType;
    }
    var statusMatch = !_iaFilterStatus || a.status === _iaFilterStatus;
    var searchMatch = !_iaSearchTerm   ||
      a.clientName.toLowerCase().includes(_iaSearchTerm) ||
      a.accountNum.toLowerCase().includes(_iaSearchTerm) ||
      a.accountType.toLowerCase().includes(_iaSearchTerm) ||
      (a.annuitySubType && a.annuitySubType.toLowerCase().includes(_iaSearchTerm));
    return typeMatch && statusMatch && searchMatch;
  });
}

function iaRenderAccountCard(a) {
  var active = _iaActiveAccount === a.id ? ' ia-card-active' : '';
  var statusIcon = {
    'Active':         'fa-check-circle',
    'Review Due':     'fa-exclamation-circle',
    'Funding Pending':'fa-hourglass-half'
  }[a.status] || 'fa-circle';
  var statusColor = {
    'Active':         '#059669',
    'Review Due':     '#d97706',
    'Funding Pending':'#0891b2'
  }[a.status] || '#64748b';

  var retColor = a.returnYTD > 0 ? '#059669' : a.returnYTD < 0 ? '#dc2626' : '#64748b';
  var driftBadge = a.driftAlert
    ? '<span class="ia-drift-badge"><i class="fas fa-balance-scale"></i> Drift ' + a.driftScore.toFixed(1) + '%</span>'
    : '';
  var rmdBadge = a.rmdDue
    ? '<span class="ia-rmd-badge"><i class="fas fa-calendar-exclamation"></i> RMD</span>'
    : '';
  var tlhBadge = a.tlhOpportunity > 0
    ? '<span class="ia-tlh-badge"><i class="fas fa-leaf"></i> TLH $' + (a.tlhOpportunity/1000).toFixed(1) + 'K</span>'
    : '';

  // Mini allocation bar
  var allocBar = '';
  if (a.aum > 0) {
    var tc = a.currentAlloc;
    allocBar = '<div class="ia-alloc-mini">' +
      (tc.usEquity   ? '<div class="ia-alloc-seg ia-seg-us"    style="width:' + tc.usEquity    + '%"  title="US Equity ' + tc.usEquity + '%"></div>' : '') +
      (tc.intlEquity ? '<div class="ia-alloc-seg ia-seg-intl"  style="width:' + tc.intlEquity  + '%"  title="Intl Equity ' + tc.intlEquity + '%"></div>' : '') +
      (tc.fixedIncome? '<div class="ia-alloc-seg ia-seg-fi"    style="width:' + tc.fixedIncome + '%"  title="Fixed Income ' + tc.fixedIncome + '%"></div>' : '') +
      (tc.alternatives?'<div class="ia-alloc-seg ia-seg-alt"   style="width:' + tc.alternatives+ '%"  title="Alternatives ' + tc.alternatives + '%"></div>' : '') +
      (tc.cash       ? '<div class="ia-alloc-seg ia-seg-cash"  style="width:' + tc.cash        + '%"  title="Cash ' + tc.cash + '%"></div>' : '') +
      '</div>';
  }

  return '<div class="ia-card' + active + '" onclick="iaOpenAccount(\'' + a.id + '\')">' +
    '<div class="ia-card-top">' +
      '<div class="ia-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
      '<div class="ia-card-info">' +
        '<div class="ia-card-client">' + a.clientName + '</div>' +
        '<div class="ia-card-acct"><i class="fas fa-folder"></i> ' + a.accountNum + ' · ' + a.accountType + (a.annuitySubType ? ' — ' + a.annuitySubType : '') + '</div>' +
      '</div>' +
      '<div class="ia-card-aum">' +
        '<div class="ia-card-aum-val">' + a.aumFmt + '</div>' +
        '<div class="ia-card-ret" style="color:' + retColor + '">' + a.returnYTDFmt + ' YTD</div>' +
      '</div>' +
    '</div>' +
    '<div class="ia-card-badges">' +
      '<span class="ia-status-pill ' + a.statusCls + '"><i class="fas ' + statusIcon + '"></i> ' + a.status + '</span>' +
      driftBadge + rmdBadge + tlhBadge +
    '</div>' +
    allocBar +
    '<div class="ia-card-footer">' +
      '<span class="ia-card-type-chip"><i class="fas fa-briefcase"></i> ' + a.riskProfile + '</span>' +
      '<span class="ia-card-horizon"><i class="fas fa-clock"></i> ' + a.horizon + '</span>' +
    '</div>' +
  '</div>';
}

/* ═══════════════════════════════════════════════════════════════════
   ACCOUNT DETAIL
   ═══════════════════════════════════════════════════════════════════ */
function iaOpenAccount(id) {
  _iaActiveAccount = id;
  _iaActiveTab = 'overview';
  iaRenderAccountQueue();

  var a = iaAccounts.find(function(x) { return x.id === id; });
  if (!a) return;

  var empty = document.getElementById('ia-detail-empty');
  var panel = document.getElementById('ia-detail-panel');
  if (empty) empty.style.display = 'none';
  if (!panel) return;
  panel.style.display = 'block';
  panel.innerHTML = iaBuildDetailHTML(a);
}

function iaBuildDetailHTML(a) {
  var statusColor = {
    'Active':'#059669','Review Due':'#d97706','Funding Pending':'#0891b2'
  }[a.status] || '#64748b';

  var retColor = a.returnYTD > 0 ? '#059669' : a.returnYTD < 0 ? '#dc2626' : '#64748b';

  var isAnnuity = a.annuityDetails != null;
  var tabs = [
    { id:'overview',    icon:'fa-th-large',      label:'Overview'    },
    { id:'portfolio',   icon:'fa-chart-pie',      label:'Portfolio'   },
    { id:'rebalance',   icon:'fa-balance-scale',  label:'Rebalance'   },
    { id:'ai',          icon:'fa-robot',          label:'AI Insights' },
    { id:'timeline',    icon:'fa-stream',         label:'Timeline'    }
  ];
  if (isAnnuity) tabs.splice(1, 0, { id:'annuity', icon:'fa-shield-alt', label:'Annuity Details' });

  var tabBtns = tabs.map(function(t) {
    var active = t.id === _iaActiveTab ? ' ia-tab-active' : '';
    return '<button class="ia-tab-btn' + active + '" onclick="iaSwitchTab(\'' + t.id + '\',this)">' +
      '<i class="fas ' + t.icon + '"></i> ' + t.label + '</button>';
  }).join('');

  var metaItems = [
    { label:'Account #', val: a.accountNum },
    { label:'Type', val: a.accountType },
    { label:'Custodian', val: a.custodian },
    { label:'Opened', val: a.openDate },
    { label:'Risk Profile', val: a.riskProfile },
    { label:'Horizon', val: a.horizon },
    { label:'Advisory Fee', val: a.feePct },
    { label:'Benchmark', val: a.benchmark }
  ];

  var metaHTML = metaItems.map(function(m) {
    return '<div class="ia-det-meta-item"><span class="ia-det-meta-lbl">' + m.label + '</span><span class="ia-det-meta-val">' + m.val + '</span></div>';
  }).join('');

  var panelContent = iaRenderTab(a, _iaActiveTab);

  return '<div class="ia-detail-wrap">' +

    // Header
    '<div class="ia-det-header">' +
      '<div class="ia-det-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
      '<div class="ia-det-title-wrap">' +
        '<div class="ia-det-client">' + a.clientName + '</div>' +
        '<div class="ia-det-acct">' + a.accountNum + ' · ' + a.accountType + '</div>' +
        (a.annuitySubType ? '<div class="ia-det-prog-desc"><i class="fas fa-umbrella-beach"></i> ' + a.annuitySubType + '</div>' : '') +
        '<div class="ia-det-meta-row">' + metaHTML + '</div>' +
      '</div>' +
      '<div class="ia-det-kpi-strip">' +
        '<div class="ia-det-kpi">' +
          '<div class="ia-det-kpi-val">' + a.aumFmt + '</div>' +
          '<div class="ia-det-kpi-lbl">AUM</div>' +
        '</div>' +
        '<div class="ia-det-kpi">' +
          '<div class="ia-det-kpi-val" style="color:' + retColor + '">' + a.returnYTDFmt + '</div>' +
          '<div class="ia-det-kpi-lbl">Return YTD</div>' +
        '</div>' +
        '<div class="ia-det-kpi">' +
          '<div class="ia-det-kpi-val">' + (a.alpha || '—') + '</div>' +
          '<div class="ia-det-kpi-lbl">Alpha</div>' +
        '</div>' +
        '<div class="ia-det-kpi">' +
          '<div class="ia-det-kpi-val" style="background:' + statusColor + '20;color:' + statusColor + ';padding:2px 8px;border-radius:20px;font-size:11px">' + a.status + '</div>' +
          '<div class="ia-det-kpi-lbl">Status</div>' +
        '</div>' +
      '</div>' +
    '</div>' +

    // Funding banner (if pending)
    (a.status === 'Funding Pending' && a.fundingDetails ? iaRenderFundingBanner(a) : '') +

    // RMD banner (if due)
    (a.rmdDue ? '<div class="ia-rmd-banner"><i class="fas fa-exclamation-triangle"></i> <strong>RMD Due:</strong> $' + a.rmdAmount.toLocaleString() + ' must be distributed by ' + a.rmdDeadline + ' — IRS penalty 25% of undistributed amount. <button class="ia-rmd-process-btn" onclick="iaProcessRMD(\'' + a.id + '\')">Process RMD</button></div>' : '') +

    // Tabs
    '<div class="ia-tabs">' + tabBtns + '</div>' +
    '<div class="ia-tab-panels">' +
      '<div class="ia-tab-panel" id="ia-panel-' + _iaActiveTab + '">' + panelContent + '</div>' +
    '</div>' +

  '</div>';
}

function iaRenderFundingBanner(a) {
  var fd = a.fundingDetails;
  return '<div class="ia-funding-banner">' +
    '<div class="ia-fb-icon"><i class="fas fa-hourglass-half"></i></div>' +
    '<div class="ia-fb-info">' +
      '<div class="ia-fb-title">Account Funding In Progress</div>' +
      '<div class="ia-fb-detail">Initial deposit: ' + fd.initialDeposit + ' · ACAT: ' + fd.acatTransfer + ' · Expected: <strong>' + fd.expectedFundingDate + '</strong></div>' +
    '</div>' +
    '<div class="ia-fb-badges">' +
      '<span class="ia-fb-badge ok"><i class="fas fa-check"></i> IMA Signed</span>' +
      '<span class="ia-fb-badge ok"><i class="fas fa-check"></i> Suitability Approved</span>' +
      '<span class="ia-fb-badge pending"><i class="fas fa-clock"></i> Awaiting Funds</span>' +
    '</div>' +
  '</div>';
}

function iaSwitchTab(tab, el) {
  _iaActiveTab = tab;
  document.querySelectorAll('.ia-tab-btn').forEach(function(b) { b.classList.remove('ia-tab-active'); });
  if (el) el.classList.add('ia-tab-active');
  var panelEl = document.querySelector('.ia-tab-panel');
  if (!panelEl) return;
  panelEl.id = 'ia-panel-' + tab;
  var a = iaAccounts.find(function(x) { return x.id === _iaActiveAccount; });
  if (a) panelEl.innerHTML = iaRenderTab(a, tab);
}

function iaRenderTab(a, tab) {
  if (tab === 'overview')  return iaRenderOverviewTab(a);
  if (tab === 'annuity')   return iaRenderAnnuityTab(a);
  if (tab === 'portfolio') return iaRenderPortfolioTab(a);
  if (tab === 'rebalance') return iaRenderRebalanceTab(a);
  if (tab === 'ai')        return iaRenderAITab(a);
  if (tab === 'timeline')  return iaRenderTimelineTab(a);
  return '';
}

/* ── Overview Tab ── */
function iaRenderOverviewTab(a) {
  if (a.annuityDetails) return iaRenderAnnuityOverview(a);
  var tc = a.targetAlloc;
  var cc = a.currentAlloc;

  var allocRows = [
    { label:'US Equity',    target:tc.usEquity,    current:cc.usEquity,    color:'#003087' },
    { label:'Intl Equity',  target:tc.intlEquity,  current:cc.intlEquity,  color:'#0891b2' },
    { label:'Fixed Income', target:tc.fixedIncome, current:cc.fixedIncome, color:'#059669' },
    { label:'Alternatives', target:tc.alternatives,current:cc.alternatives,color:'#7c3aed' },
    { label:'Cash',         target:tc.cash,        current:cc.cash,        color:'#d97706' }
  ].filter(function(r) { return r.target > 0 || r.current > 0; });

  var allocHTML = allocRows.map(function(r) {
    var drift = r.current - r.target;
    var driftStr = drift > 0 ? '<span style="color:#dc2626">+' + drift + '%</span>' : drift < 0 ? '<span style="color:#0891b2">' + drift + '%</span>' : '<span style="color:#059669">0%</span>';
    var driftCls = Math.abs(drift) >= 5 ? ' ia-alloc-row-alert' : '';
    return '<div class="ia-alloc-row' + driftCls + '">' +
      '<div class="ia-alloc-label" style="color:' + r.color + '">' + r.label + '</div>' +
      '<div class="ia-alloc-bars">' +
        '<div class="ia-alloc-bar-wrap">' +
          '<div class="ia-alloc-target-bar" style="width:' + r.target + '%;background:' + r.color + '30;border:1px solid ' + r.color + '60"></div>' +
        '</div>' +
        '<div class="ia-alloc-bar-wrap">' +
          '<div class="ia-alloc-current-bar" style="width:' + r.current + '%;background:' + r.color + '"></div>' +
        '</div>' +
      '</div>' +
      '<div class="ia-alloc-pcts">' +
        '<span class="ia-alloc-target-pct">' + r.target + '%</span>' +
        '<span class="ia-alloc-current-pct">' + r.current + '%</span>' +
        '<span class="ia-alloc-drift">' + driftStr + '</span>' +
      '</div>' +
    '</div>';
  }).join('');

  var quickActions = [
    { icon:'fa-balance-scale', label:'Rebalance', fn:'iaSwitchTab(\'rebalance\',null)', cls:'' },
    { icon:'fa-robot',         label:'AI Review',  fn:'iaSwitchTab(\'ai\',null)',        cls:'' },
    { icon:'fa-file-pdf',      label:'Q Report',   fn:'iaGenerateReport(\'' + a.id + '\')', cls:'' },
    { icon:'fa-envelope',      label:'Send to Client', fn:'iaSendReport(\'' + a.id + '\')', cls:'' }
  ];

  return '<div class="ia-overview-grid">' +

    '<div class="ia-overview-left">' +

      '<div class="ia-ov-section">' +
        '<div class="ia-ov-section-title"><i class="fas fa-chart-pie"></i> Allocation vs Target</div>' +
        '<div class="ia-alloc-legend"><span class="ia-legend-item"><span class="ia-legend-box" style="background:#e2e8f0;border:1px solid #94a3b8"></span>Target</span><span class="ia-legend-item"><span class="ia-legend-box" style="background:#003087"></span>Current</span></div>' +
        '<div class="ia-alloc-table">' + allocHTML + '</div>' +
      '</div>' +

      '<div class="ia-ov-section">' +
        '<div class="ia-ov-section-title"><i class="fas fa-bolt"></i> Quick Actions</div>' +
        '<div class="ia-quick-actions">' +
          quickActions.map(function(q) {
            return '<button class="ia-qa-btn" onclick="' + q.fn + '"><i class="fas ' + q.icon + '"></i><span>' + q.label + '</span></button>';
          }).join('') +
        '</div>' +
      '</div>' +

    '</div>' +

    '<div class="ia-overview-right">' +

      '<div class="ia-ov-section">' +
        '<div class="ia-ov-section-title"><i class="fas fa-tachometer-alt"></i> Performance</div>' +
        '<div class="ia-perf-grid">' +
          '<div class="ia-perf-card"><div class="ia-perf-val green">' + a.returnYTDFmt + '</div><div class="ia-perf-lbl">Return YTD</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val blue">' + a.benchmarkYTD + '%</div><div class="ia-perf-lbl">Benchmark YTD</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val ' + (parseFloat(a.alpha) >= 0 ? 'green' : 'red') + '">' + a.alpha + '</div><div class="ia-perf-lbl">Alpha</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val">' + (a.sharpe ? a.sharpe.toFixed(2) : '—') + '</div><div class="ia-perf-lbl">Sharpe Ratio</div></div>' +
        '</div>' +
      '</div>' +

      (a.driftAlert ? '<div class="ia-ov-section ia-ov-alert">' +
        '<div class="ia-ov-section-title ia-alert-title"><i class="fas fa-exclamation-triangle"></i> Drift Alert — ' + a.driftScore.toFixed(1) + '% from Target</div>' +
        '<div class="ia-alert-body">Rebalancing recommended to restore target allocation. ' + a.rebalanceTrades.length + ' trades identified.</div>' +
        '<button class="ia-alert-btn" onclick="iaSwitchTab(\'rebalance\',null)"><i class="fas fa-balance-scale"></i> View Rebalance Plan</button>' +
      '</div>' : '') +

      (a.rmdDue ? '<div class="ia-ov-section ia-ov-rmd">' +
        '<div class="ia-ov-section-title ia-rmd-title"><i class="fas fa-calendar-exclamation"></i> RMD Required — ' + a.rmdDeadline + '</div>' +
        '<div class="ia-rmd-amount">$' + a.rmdAmount.toLocaleString() + ' <span>must be distributed</span></div>' +
        '<button class="ia-rmd-btn" onclick="iaProcessRMD(\'' + a.id + '\')"><i class="fas fa-paper-plane"></i> Process RMD</button>' +
      '</div>' : '') +

      (a.tlhOpportunity > 0 ? '<div class="ia-ov-section ia-ov-tlh">' +
        '<div class="ia-ov-section-title ia-tlh-title"><i class="fas fa-leaf"></i> Tax-Loss Harvesting Opportunity</div>' +
        '<div class="ia-tlh-amount">$' + a.tlhOpportunity.toLocaleString() + ' <span>estimated tax savings</span></div>' +
        '<div class="ia-tlh-positions">' + a.tlhPositions.map(function(p) { return '<div class="ia-tlh-pos"><i class="fas fa-angle-right"></i>' + p + '</div>'; }).join('') + '</div>' +
        '<button class="ia-tlh-btn" onclick="iaExecuteTLH(\'' + a.id + '\')"><i class="fas fa-leaf"></i> Execute TLH</button>' +
      '</div>' : '') +

    '</div>' +

  '</div>';
}

/* ── Annuity Overview (replaces allocation grid for annuity accounts) ── */
function iaRenderAnnuityOverview(a) {
  var ad = a.annuityDetails;
  var retColor = a.returnYTD > 0 ? '#059669' : '#64748b';

  // Annuity category badge
  var isDeferred  = ad.type && (ad.type.indexOf('Deferred') !== -1 || ad.type.indexOf('Variable') !== -1 || ad.type.indexOf('Hybrid') !== -1 || ad.type.indexOf('IndexFlex') !== -1);
  var isImmediate = ad.type && ad.type.indexOf('Immediate') !== -1;
  var catLabel    = isImmediate ? 'Immediate Income Annuity' : 'Deferred Annuity';
  var catIcon     = isImmediate ? 'fa-bolt' : 'fa-hourglass-half';
  var catColor    = isImmediate ? '#059669' : '#d97706';

  // Key specs from annuityDetails — cover all three product types
  var specRows = [];
  if (ad.guaranteedRate)  specRows.push({ lbl:'Guaranteed Rate',    val: ad.guaranteedRate,   icon:'fa-lock',           color:'#059669' });
  if (ad.indexedAccount)  specRows.push({ lbl:'Indexed Account',    val: ad.indexedAccount,   icon:'fa-chart-area',     color:'#003087' });
  if (ad.fixedAccount)    specRows.push({ lbl:'Fixed Account',      val: ad.fixedAccount,     icon:'fa-shield-alt',     color:'#059669' });
  if (ad.mAndE)           specRows.push({ lbl:'M&E Charge',         val: ad.mAndE,            icon:'fa-percent',        color:'#64748b' });
  if (ad.fundExpenses)    specRows.push({ lbl:'Fund Expenses',      val: ad.fundExpenses,     icon:'fa-coins',          color:'#64748b' });
  if (ad.surrenderPeriod) specRows.push({ lbl:'Surrender Period',   val: ad.surrenderPeriod,  icon:'fa-calendar-alt',   color:'#7c3aed' });
  if (ad.deathBenefit)    specRows.push({ lbl:'Death Benefit',      val: ad.deathBenefit,     icon:'fa-heart',          color:'#dc2626' });
  if (ad.incomeRider)     specRows.push({ lbl:'Income Rider',       val: ad.incomeRider,      icon:'fa-hand-holding-usd', color:'#0891b2' });
  if (ad.taxStatus)       specRows.push({ lbl:'Tax Status',         val: ad.taxStatus,        icon:'fa-landmark',       color:'#7c3aed' });

  var specsHTML = specRows.map(function(s) {
    return '<div class="ia-ann-spec-row">' +
      '<div class="ia-ann-spec-icon" style="background:' + s.color + '18;color:' + s.color + '"><i class="fas ' + s.icon + '"></i></div>' +
      '<div class="ia-ann-spec-lbl">' + s.lbl + '</div>' +
      '<div class="ia-ann-spec-val">' + s.val + '</div>' +
    '</div>';
  }).join('');

  // Income path timeline
  var incomePathHTML = '';
  if (isDeferred) {
    incomePathHTML =
      '<div class="ia-ann-path">' +
        '<div class="ia-ann-path-title"><i class="fas fa-route"></i> Guaranteed Income Path</div>' +
        '<div class="ia-ann-path-steps">' +
          '<div class="ia-ann-path-step active">' +
            '<div class="ia-ann-path-dot" style="background:#003087"></div>' +
            '<div class="ia-ann-path-body"><div class="ia-ann-path-label">Accumulation Phase</div><div class="ia-ann-path-sub">Tax-deferred growth · ' + (ad.guaranteedRate || ad.indexedAccount ? 'Guaranteed / Indexed' : 'Sub-account') + ' crediting</div></div>' +
          '</div>' +
          '<div class="ia-ann-path-connector"></div>' +
          '<div class="ia-ann-path-step">' +
            '<div class="ia-ann-path-dot" style="background:#d97706"></div>' +
            '<div class="ia-ann-path-body"><div class="ia-ann-path-label">Income Election</div><div class="ia-ann-path-sub">Activate income rider or annuitize at retirement</div></div>' +
          '</div>' +
          '<div class="ia-ann-path-connector"></div>' +
          '<div class="ia-ann-path-step">' +
            '<div class="ia-ann-path-dot" style="background:#059669"></div>' +
            '<div class="ia-ann-path-body"><div class="ia-ann-path-label">Distribution Phase</div><div class="ia-ann-path-sub">Guaranteed lifetime income · RMD compliant</div></div>' +
          '</div>' +
        '</div>' +
      '</div>';
  } else {
    incomePathHTML =
      '<div class="ia-ann-path">' +
        '<div class="ia-ann-path-title"><i class="fas fa-route"></i> Income in Two Ways</div>' +
        '<div class="ia-ann-path-steps">' +
          '<div class="ia-ann-path-step active">' +
            '<div class="ia-ann-path-dot" style="background:#059669"></div>' +
            '<div class="ia-ann-path-body"><div class="ia-ann-path-label">Immediate Income Annuity</div><div class="ia-ann-path-sub">Income starts now · consistent, predictable payments</div></div>' +
          '</div>' +
          '<div class="ia-ann-path-connector"></div>' +
          '<div class="ia-ann-path-step">' +
            '<div class="ia-ann-path-dot" style="background:#0891b2"></div>' +
            '<div class="ia-ann-path-body"><div class="ia-ann-path-label">Guaranteed for Life</div><div class="ia-ann-path-sub">Protects savings · supports lifestyle · financial reliability</div></div>' +
          '</div>' +
        '</div>' +
      '</div>';
  }

  var quickActions = [
    { icon:'fa-shield-alt', label:'Annuity Details', fn:'iaSwitchTab(\'annuity\',null)'   },
    { icon:'fa-robot',      label:'AI Review',        fn:'iaSwitchTab(\'ai\',null)'         },
    { icon:'fa-file-pdf',   label:'Illustration',     fn:'iaGenerateReport(\'' + a.id + '\')' },
    { icon:'fa-envelope',   label:'Send to Client',   fn:'iaSendReport(\'' + a.id + '\')'    }
  ];

  return '<div class="ia-overview-grid">' +

    '<div class="ia-overview-left">' +

      // Category badge + specs
      '<div class="ia-ov-section">' +
        '<div class="ia-ann-cat-badge" style="background:' + catColor + '18;border:1.5px solid ' + catColor + '40;color:' + catColor + '">' +
          '<i class="fas ' + catIcon + '"></i> ' + catLabel +
        '</div>' +
        '<div class="ia-ann-specs">' + specsHTML + '</div>' +
      '</div>' +

      // Quick actions
      '<div class="ia-ov-section">' +
        '<div class="ia-ov-section-title"><i class="fas fa-bolt"></i> Quick Actions</div>' +
        '<div class="ia-quick-actions">' +
          quickActions.map(function(q) {
            return '<button class="ia-qa-btn" onclick="' + q.fn + '"><i class="fas ' + q.icon + '"></i><span>' + q.label + '</span></button>';
          }).join('') +
        '</div>' +
      '</div>' +

    '</div>' +

    '<div class="ia-overview-right">' +

      // Performance
      '<div class="ia-ov-section">' +
        '<div class="ia-ov-section-title"><i class="fas fa-tachometer-alt"></i> Performance</div>' +
        '<div class="ia-perf-grid">' +
          '<div class="ia-perf-card"><div class="ia-perf-val green">' + a.returnYTDFmt + '</div><div class="ia-perf-lbl">Return YTD</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val blue">' + a.benchmarkYTD + '%</div><div class="ia-perf-lbl">Benchmark</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val">' + (a.fee ? '$' + a.fee.toLocaleString() : '$0') + '</div><div class="ia-perf-lbl">Annual Cost</div></div>' +
          '<div class="ia-perf-card"><div class="ia-perf-val" style="color:#7c3aed">' + a.feePct.split(' ')[0] + '</div><div class="ia-perf-lbl">Total Fee</div></div>' +
        '</div>' +
      '</div>' +

      // Income path
      incomePathHTML +

      // RMD banner if applicable
      (a.rmdDue ? '<div class="ia-ov-section ia-ov-rmd">' +
        '<div class="ia-ov-section-title ia-rmd-title"><i class="fas fa-calendar-exclamation"></i> RMD Required — ' + a.rmdDeadline + '</div>' +
        '<div class="ia-rmd-amount">$' + a.rmdAmount.toLocaleString() + ' <span>must be distributed</span></div>' +
        '<button class="ia-rmd-btn" onclick="iaProcessRMD(\'' + a.id + '\')"><i class="fas fa-paper-plane"></i> Process RMD</button>' +
      '</div>' : '') +

      // Drift alert (VA sub-accounts can drift)
      (a.driftAlert ? '<div class="ia-ov-section ia-ov-alert">' +
        '<div class="ia-ov-section-title ia-alert-title"><i class="fas fa-exclamation-triangle"></i> Sub-Account Drift — ' + a.driftScore.toFixed(1) + '% from Target</div>' +
        '<div class="ia-alert-body">Sub-account rebalancing recommended. ' + a.rebalanceTrades.length + ' trades identified.</div>' +
        '<button class="ia-alert-btn" onclick="iaSwitchTab(\'rebalance\',null)"><i class="fas fa-balance-scale"></i> View Rebalance Plan</button>' +
      '</div>' : '') +

    '</div>' +

  '</div>';
}

/* ── Annuity Details Tab ── */
function iaRenderAnnuityTab(a) {
  var ad = a.annuityDetails;
  if (!ad) return '<div class="ia-empty-holdings"><p>No annuity details available.</p></div>';

  var isFixed    = ad.type === 'Fixed Deferred';
  var isVariable = ad.type === 'Variable Annuity';
  var isHybrid   = ad.type && ad.type.indexOf('Hybrid') !== -1 || (ad.type && ad.type.indexOf('IndexFlex') !== -1);

  // ── NYL product category header ──
  var prodMap = {
    'Fixed Deferred':    { label:'Fixed Deferred Annuity',         color:'#d97706', bg:'#fffbeb', icon:'fa-shield-alt',     cat:'Deferred',  sub:'Guaranteed interest rate growth with principal protection' },
    'Variable Annuity':  { label:'Variable Annuity',               color:'#7c3aed', bg:'#f5f3ff', icon:'fa-chart-line',     cat:'Deferred',  sub:'Market-linked sub-account growth with optional income rider' },
    'Hybrid Variable (IndexFlex)': { label:'Hybrid Variable Annuity (IndexFlex)', color:'#0891b2', bg:'#ecfeff', icon:'fa-balance-scale', cat:'Deferred', sub:'S&P 500 indexed with 0% floor — growth potential, no downside risk' }
  };
  var prod = prodMap[ad.type] || { label: ad.type, color:'#64748b', bg:'#f8fafc', icon:'fa-umbrella-beach', cat:'Deferred', sub:'' };

  // ── NYL income ways section ──
  var incomeHTML = '';
  if (isFixed) {
    incomeHTML =
      '<div class="ia-ann-income-section">' +
        '<div class="ia-ann-income-title"><i class="fas fa-hand-holding-usd"></i> You can receive guaranteed income in two ways</div>' +
        '<div class="ia-ann-income-ways">' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-bolt" style="color:#059669"></i> Immediate income annuities</div>' +
            '<div class="ia-ann-income-card-desc">Start to receive income now, for as long as you need it.</div>' +
            '<div class="ia-ann-income-card-link"><i class="fas fa-arrow-right"></i> See immediate income options</div>' +
          '</div>' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-hourglass-half" style="color:#d97706"></i> Deferred income annuities</div>' +
            '<div class="ia-ann-income-card-desc">Receive income for life and larger payouts by delaying them for up to 40 years.</div>' +
            '<div class="ia-ann-income-card-link"><i class="fas fa-arrow-right"></i> See deferred income options</div>' +
          '</div>' +
        '</div>' +
      '</div>';
  } else if (isVariable) {
    incomeHTML =
      '<div class="ia-ann-income-section">' +
        '<div class="ia-ann-income-title"><i class="fas fa-hand-holding-usd"></i> Guaranteed Income Options</div>' +
        '<div class="ia-ann-income-ways">' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-umbrella" style="color:#7c3aed"></i> GMIB Rider — Guaranteed Minimum Income Benefit</div>' +
            '<div class="ia-ann-income-card-desc">' + (ad.incomeRider || 'Optional GMIB rider available') + '</div>' +
            '<div class="ia-ann-income-card-sub"><strong>Best for:</strong> Clients wanting guaranteed income floor regardless of market performance</div>' +
          '</div>' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-chart-line" style="color:#059669"></i> Death Benefit Protection</div>' +
            '<div class="ia-ann-income-card-desc">' + (ad.deathBenefit || 'Death benefit protection included') + '</div>' +
            '<div class="ia-ann-income-card-sub"><strong>Best for:</strong> Clients who want estate protection alongside market growth</div>' +
          '</div>' +
        '</div>' +
      '</div>';
  } else {
    // Hybrid / IndexFlex
    incomeHTML =
      '<div class="ia-ann-income-section">' +
        '<div class="ia-ann-income-title"><i class="fas fa-hand-holding-usd"></i> IndexFlex — How Growth Works</div>' +
        '<div class="ia-ann-income-ways">' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-chart-area" style="color:#003087"></i> S&amp;P 500 Indexed Account</div>' +
            '<div class="ia-ann-income-card-desc">' + (ad.indexedAccount || 'S&P 500 with 0% floor / 11% cap') + '</div>' +
            '<div class="ia-ann-income-card-sub"><strong>Best for:</strong> Clients who want market-linked growth with zero downside risk</div>' +
          '</div>' +
          '<div class="ia-ann-income-card">' +
            '<div class="ia-ann-income-card-title"><i class="fas fa-shield-alt" style="color:#059669"></i> Fixed Guaranteed Account</div>' +
            '<div class="ia-ann-income-card-desc">' + (ad.fixedAccount || 'Guaranteed 3.0% fixed rate') + '</div>' +
            '<div class="ia-ann-income-card-sub"><strong>Best for:</strong> Portion of premium seeking stable, guaranteed crediting each year</div>' +
          '</div>' +
        '</div>' +
      '</div>';
  }

  // ── Four core benefits (NYL style) ──
  var benefitsHTML =
    '<div class="ia-ann-benefits">' +
      '<div class="ia-ann-benefits-title"><i class="fas fa-star"></i> How income annuities can help in retirement</div>' +
      '<div class="ia-ann-benefits-grid">' +
        '<div class="ia-ann-benefit-item">' +
          '<div class="ia-ann-benefit-icon"><i class="fas fa-lock"></i></div>' +
          '<div class="ia-ann-benefit-name">Guaranteed income</div>' +
          '<div class="ia-ann-benefit-desc">Your retirement savings are converted into an income stream that pays you for as long as you need</div>' +
        '</div>' +
        '<div class="ia-ann-benefit-item">' +
          '<div class="ia-ann-benefit-icon"><i class="fas fa-medal"></i></div>' +
          '<div class="ia-ann-benefit-name">Financial reliability</div>' +
          '<div class="ia-ann-benefit-desc">NYL has been paying benefits for 178+ years and always puts clients\' financial interests first</div>' +
        '</div>' +
        '<div class="ia-ann-benefit-item">' +
          '<div class="ia-ann-benefit-icon"><i class="fas fa-piggy-bank"></i></div>' +
          '<div class="ia-ann-benefit-name">Stretching your savings</div>' +
          '<div class="ia-ann-benefit-desc">Alleviate worries about running out of money and possibly earn more with annuities offering potential dividends</div>' +
        '</div>' +
        '<div class="ia-ann-benefit-item">' +
          '<div class="ia-ann-benefit-icon"><i class="fas fa-sliders-h"></i></div>' +
          '<div class="ia-ann-benefit-name">Personal flexibility</div>' +
          '<div class="ia-ann-benefit-desc">Options to set the start date and amounts of income payments, based on personal needs</div>' +
        '</div>' +
      '</div>' +
    '</div>';

  // ── Contract details grid ──
  var contractItems = [];
  if (ad.guaranteedRate)  contractItems.push({ lbl:'Guaranteed Rate',    val:ad.guaranteedRate   });
  if (ad.indexedAccount)  contractItems.push({ lbl:'Indexed Account',    val:ad.indexedAccount   });
  if (ad.fixedAccount)    contractItems.push({ lbl:'Fixed Account',      val:ad.fixedAccount     });
  if (ad.mAndE)           contractItems.push({ lbl:'M&E Charge',         val:ad.mAndE            });
  if (ad.fundExpenses)    contractItems.push({ lbl:'Fund Expenses',      val:ad.fundExpenses     });
  if (ad.surrenderPeriod) contractItems.push({ lbl:'Surrender Period',   val:ad.surrenderPeriod  });
  if (ad.deathBenefit)    contractItems.push({ lbl:'Death Benefit',      val:ad.deathBenefit     });
  if (ad.incomeRider)     contractItems.push({ lbl:'Income Rider',       val:ad.incomeRider      });
  if (ad.taxStatus)       contractItems.push({ lbl:'Tax Treatment',      val:ad.taxStatus        });

  var contractHTML = contractItems.map(function(c) {
    return '<div class="ia-ann-contract-row"><span class="ia-ann-contract-lbl">' + c.lbl + '</span><span class="ia-ann-contract-val">' + c.val + '</span></div>';
  }).join('');

  // ── Projection table (illustrative) ──
  var projRows = '';
  var base = a.aum;
  if (isFixed && ad.guaranteedRate) {
    var rate = parseFloat(ad.guaranteedRate) / 100 || 0.0475;
    [1,3,5,10].forEach(function(yr) {
      var val = Math.round(base * Math.pow(1 + rate, yr));
      projRows += '<tr><td>' + yr + ' yr</td><td>$' + val.toLocaleString() + '</td><td>' + (rate*100).toFixed(2) + '%</td><td style="color:#059669">Protected</td></tr>';
    });
  } else if (isHybrid) {
    [[1,7.2,0],[3,6.5,0],[5,7.0,0],[10,6.8,0]].forEach(function(r) {
      var val = Math.round(base * Math.pow(1 + r[1]/100, r[0]));
      projRows += '<tr><td>' + r[0] + ' yr</td><td>$' + val.toLocaleString() + '</td><td>' + r[1] + '%</td><td style="color:#059669">0% floor</td></tr>';
    });
  } else if (isVariable) {
    [[1,9.8,8],[3,8.5,7],[5,9.2,8],[10,8.8,7.5]].forEach(function(r) {
      var val = Math.round(base * Math.pow(1 + r[1]/100, r[0]));
      projRows += '<tr><td>' + r[0] + ' yr</td><td>$' + val.toLocaleString() + '</td><td>' + r[1] + '%</td><td style="color:#0891b2">' + r[2] + '% benchmark</td></tr>';
    });
  }

  var projHTML = projRows ? (
    '<div class="ia-ann-proj">' +
      '<div class="ia-ann-proj-title"><i class="fas fa-chart-bar"></i> Illustrative Projection</div>' +
      '<table class="ia-ann-proj-table">' +
        '<thead><tr><th>Year</th><th>Est. Value</th><th>Rate</th><th>Protection</th></tr></thead>' +
        '<tbody>' + projRows + '</tbody>' +
      '</table>' +
      '<div class="ia-ann-proj-note"><i class="fas fa-info-circle"></i> Illustration only — actual results may vary. Past performance not guaranteed.</div>' +
    '</div>'
  ) : '';

  return '<div class="ia-annuity-tab">' +

    // Product header
    '<div class="ia-ann-prod-header" style="background:' + prod.bg + ';border-left:4px solid ' + prod.color + '">' +
      '<div class="ia-ann-prod-icon" style="background:' + prod.color + '"><i class="fas ' + prod.icon + '"></i></div>' +
      '<div class="ia-ann-prod-info">' +
        '<div class="ia-ann-prod-name">' + prod.label + '</div>' +
        '<div class="ia-ann-prod-sub">' + prod.sub + '</div>' +
        '<div class="ia-ann-prod-cat"><i class="fas fa-tag"></i> ' + prod.cat + ' Annuity · Tax-Deferred · NYL</div>' +
      '</div>' +
    '</div>' +

    // Income ways
    incomeHTML +

    // Contract details
    '<div class="ia-ann-contract">' +
      '<div class="ia-ann-contract-title"><i class="fas fa-file-contract"></i> Contract Details</div>' +
      contractHTML +
    '</div>' +

    // Illustrative projection
    projHTML +

    // Core benefits
    benefitsHTML +

    // Action row
    '<div class="ia-ann-action-row">' +
      '<button class="ia-ann-action-btn primary" onclick="iaGenerateReport(\'' + a.id + '\')"><i class="fas fa-file-pdf"></i> Generate Illustration</button>' +
      '<button class="ia-ann-action-btn ghost"   onclick="iaSwitchTab(\'ai\',null)"><i class="fas fa-robot"></i> AI Insights</button>' +
      (a.rmdDue ? '<button class="ia-ann-action-btn ghost" onclick="iaProcessRMD(\'' + a.id + '\')"><i class="fas fa-calendar-check"></i> Process RMD</button>' : '') +
    '</div>' +

  '</div>';
}

/* ── Portfolio Tab ── */
function iaRenderPortfolioTab(a) {
  if (!a.holdings.length) {
    return '<div class="ia-empty-holdings"><i class="fas fa-hourglass-half"></i><p>No holdings yet — account is pending funding.</p></div>';
  }

  var statusCls = { 'overweight':'ia-hold-over', 'underweight':'ia-hold-under', 'on-target':'ia-hold-ok' };
  var statusIcon = { 'overweight':'fa-arrow-up', 'underweight':'fa-arrow-down', 'on-target':'fa-check' };

  var holdRows = a.holdings.map(function(h) {
    var sc = statusCls[h.status] || '';
    var si = statusIcon[h.status] || 'fa-circle';
    var barWidth = Math.min(h.pct, 100);
    return '<div class="ia-hold-row ' + sc + '">' +
      '<div class="ia-hold-name">' +
        '<div class="ia-hold-name-main">' + h.name + '</div>' +
        '<div class="ia-hold-type">' + h.type + '</div>' +
      '</div>' +
      '<div class="ia-hold-bar-wrap">' +
        '<div class="ia-hold-bar" style="width:' + barWidth + '%"></div>' +
      '</div>' +
      '<div class="ia-hold-pct">' + h.pct.toFixed(1) + '%</div>' +
      '<div class="ia-hold-val">$' + (h.value/1000).toFixed(0) + 'K</div>' +
      '<div class="ia-hold-ret">' + h.ret + '</div>' +
      '<div class="ia-hold-status"><span class="ia-hold-status-badge ' + sc + '"><i class="fas ' + si + '"></i> ' + h.status.replace('-',' ') + '</span></div>' +
    '</div>';
  }).join('');

  return '<div class="ia-portfolio-tab">' +
    '<div class="ia-hold-header">' +
      '<span class="ia-hold-hdr-name">Holding</span>' +
      '<span class="ia-hold-hdr-bar">Weight</span>' +
      '<span class="ia-hold-hdr-pct">%</span>' +
      '<span class="ia-hold-hdr-val">Value</span>' +
      '<span class="ia-hold-hdr-ret">Return YTD</span>' +
      '<span class="ia-hold-hdr-status">Status</span>' +
    '</div>' +
    holdRows +
    '<div class="ia-hold-total">' +
      '<span>Total Portfolio Value</span>' +
      '<span class="ia-hold-total-val">$' + (a.aum/1000).toFixed(0) + 'K</span>' +
    '</div>' +
  '</div>';
}

/* ── Rebalance Tab ── */
function iaRenderRebalanceTab(a) {
  if (!a.rebalanceTrades.length) {
    return '<div class="ia-rebalance-ok">' +
      '<div class="ia-reb-ok-icon"><i class="fas fa-check-circle"></i></div>' +
      '<div class="ia-reb-ok-title">Portfolio is On Target</div>' +
      '<div class="ia-reb-ok-sub">All asset class allocations are within ±5% of target. No rebalancing needed at this time.</div>' +
      '<div class="ia-reb-ok-meta">Next scheduled review: <strong>' + a.nextReview + '</strong></div>' +
    '</div>';
  }

  var totalSell = a.rebalanceTrades.filter(function(t) { return t.action === 'SELL'; }).reduce(function(sum, t) {
    return sum + parseFloat(t.amount.replace(/[$,]/g,''));
  }, 0);
  var totalBuy = a.rebalanceTrades.filter(function(t) { return t.action === 'BUY'; }).reduce(function(sum, t) {
    return sum + parseFloat(t.amount.replace(/[$,]/g,''));
  }, 0);

  var tradeRows = a.rebalanceTrades.map(function(t) {
    var cls = t.action === 'SELL' ? 'ia-trade-sell' : 'ia-trade-buy';
    var icon = t.action === 'SELL' ? 'fa-arrow-down' : 'fa-arrow-up';
    return '<div class="ia-trade-row ' + cls + '">' +
      '<div class="ia-trade-action"><i class="fas ' + icon + '"></i> ' + t.action + '</div>' +
      '<div class="ia-trade-security">' + t.security + '</div>' +
      '<div class="ia-trade-amount">' + t.amount + '</div>' +
      '<div class="ia-trade-reason"><i class="fas fa-info-circle"></i> ' + t.reason + '</div>' +
    '</div>';
  }).join('');

  return '<div class="ia-rebalance-tab">' +
    '<div class="ia-reb-summary">' +
      '<div class="ia-reb-drift-score">' +
        '<div class="ia-reb-drift-num">' + a.driftScore.toFixed(1) + '%</div>' +
        '<div class="ia-reb-drift-lbl">Portfolio Drift</div>' +
      '</div>' +
      '<div class="ia-reb-summary-stats">' +
        '<div class="ia-reb-stat"><span class="ia-reb-stat-val">' + a.rebalanceTrades.length + '</span><span class="ia-reb-stat-lbl">Trades Required</span></div>' +
        '<div class="ia-reb-stat"><span class="ia-reb-stat-val sell">-$' + (totalSell/1000).toFixed(1) + 'K</span><span class="ia-reb-stat-lbl">Total Sells</span></div>' +
        '<div class="ia-reb-stat"><span class="ia-reb-stat-val buy">+$' + (totalBuy/1000).toFixed(1) + 'K</span><span class="ia-reb-stat-lbl">Total Buys</span></div>' +
      '</div>' +
    '</div>' +

    '<div class="ia-trade-table">' +
      '<div class="ia-trade-header">' +
        '<span>Action</span><span>Security</span><span>Amount</span><span>Reason</span>' +
      '</div>' +
      tradeRows +
    '</div>' +

    '<div class="ia-reb-actions">' +
      '<button class="ia-reb-btn primary" onclick="iaExecuteRebalance(\'' + a.id + '\')"><i class="fas fa-play-circle"></i> Execute All Trades</button>' +
      '<button class="ia-reb-btn ghost"   onclick="iaPreviewTrades(\'' + a.id + '\')"><i class="fas fa-eye"></i> Preview Trades</button>' +
      '<button class="ia-reb-btn ghost"   onclick="iaExportTradeList(\'' + a.id + '\')"><i class="fas fa-file-export"></i> Export Trade List</button>' +
    '</div>' +

    '<div class="ia-reb-tax-note">' +
      '<i class="fas fa-info-circle"></i> <strong>Tax note:</strong> SELL trades in taxable accounts may trigger capital gains. AI has optimized trade order to minimize tax impact. Confirm with client before executing in taxable accounts.' +
    '</div>' +

  '</div>';
}

/* ── AI Insights Tab ── */
function iaRenderAITab(a) {
  var ai = a.aiInsights;
  var actionBtns = ai.actions.map(function(act, i) {
    return '<div class="ia-ai-action-item">' +
      '<span class="ia-ai-action-num">' + (i+1) + '</span>' +
      '<span class="ia-ai-action-text">' + act + '</span>' +
    '</div>';
  }).join('');

  return '<div class="ia-ai-tab">' +
    '<div class="ia-ai-headline">' +
      '<div class="ia-ai-chip"><i class="fas fa-robot"></i> AI Portfolio Intelligence</div>' +
      '<div class="ia-ai-headline-text">' + ai.headline + '</div>' +
    '</div>' +
    '<div class="ia-ai-summary-box">' +
      '<div class="ia-ai-summary-label"><i class="fas fa-brain"></i> Analysis</div>' +
      '<div class="ia-ai-summary-text">' + ai.summary + '</div>' +
    '</div>' +
    '<div class="ia-ai-actions-section">' +
      '<div class="ia-ai-actions-label"><i class="fas fa-tasks"></i> Recommended Actions</div>' +
      '<div class="ia-ai-actions-list">' + actionBtns + '</div>' +
    '</div>' +
    '<div class="ia-ai-tool-row">' +
      '<button class="ia-ai-tool-btn" onclick="iaRunDriftScan()"><i class="fas fa-balance-scale"></i> Run Drift Scan</button>' +
      '<button class="ia-ai-tool-btn" onclick="iaRunTLHScan()"><i class="fas fa-leaf"></i> TLH Scanner</button>' +
      '<button class="ia-ai-tool-btn" onclick="iaOpenRMDCenter()"><i class="fas fa-calendar-check"></i> RMD Center</button>' +
      '<button class="ia-ai-tool-btn" onclick="iaGenerateReport(\'' + a.id + '\')"><i class="fas fa-file-pdf"></i> Generate Report</button>' +
    '</div>' +
  '</div>';
}

/* ── Timeline Tab ── */
function iaRenderTimelineTab(a) {
  var typeIcons = {
    report:'fa-chart-bar', alert:'fa-exclamation-triangle', review:'fa-clipboard-check',
    rmd:'fa-calendar-check', rebalance:'fa-balance-scale', tlh:'fa-leaf',
    contribution:'fa-plus-circle', dividend:'fa-coins', open:'fa-folder-open', funding:'fa-hand-holding-usd'
  };
  var typeColors = {
    report:'#0891b2', alert:'#dc2626', review:'#4f46e5', rmd:'#d97706',
    rebalance:'#059669', tlh:'#059669', contribution:'#7c3aed', dividend:'#d97706',
    open:'#003087', funding:'#0891b2'
  };

  var rows = a.timeline.map(function(t, i) {
    var icon  = typeIcons[t.type]  || 'fa-circle';
    var color = typeColors[t.type] || '#64748b';
    var latest = i === 0 ? ' ia-tl-row-latest' : '';
    return '<div class="ia-tl-row' + latest + '">' +
      '<div class="ia-tl-dot" style="background:' + color + '"><i class="fas ' + icon + '"></i></div>' +
      '<div class="ia-tl-body">' +
        '<div class="ia-tl-date">' + t.date + '</div>' +
        '<div class="ia-tl-event">' + t.event + '</div>' +
      '</div>' +
    '</div>';
  }).join('');

  return '<div class="ia-timeline-tab">' + rows + '</div>';
}

/* ═══════════════════════════════════════════════════════════════════
   FILTER / SEARCH
   ═══════════════════════════════════════════════════════════════════ */
function iaFilterAccounts() {
  var searchEl = document.getElementById('ia-search');
  var typeEl   = document.getElementById('ia-type-filter');
  var statusEl = document.getElementById('ia-status-filter');
  _iaSearchTerm   = searchEl  ? searchEl.value.toLowerCase()  : '';
  _iaFilterType   = typeEl    ? typeEl.value    : '';
  _iaFilterStatus = statusEl  ? statusEl.value  : '';
  iaRenderAccountQueue();
}

function iaFilterByType(typeName) {
  var typeEl = document.getElementById('ia-type-filter');
  if (typeEl) {
    typeEl.value = typeName;
    iaFilterAccounts();
    var queue = document.getElementById('ia-account-queue');
    if (queue) queue.scrollIntoView({ behavior:'smooth', block:'nearest' });
  }
}

/* ═══════════════════════════════════════════════════════════════════
   DRIFT MONITOR PANEL
   ═══════════════════════════════════════════════════════════════════ */
function iaRunDriftScan() {
  var existing = document.getElementById('ia-scan-overlay-drift');
  if (existing) { existing.remove(); return; }

  var totalTrades = iaDriftAccounts.reduce(function(s,a){ return s + a.rebalanceTrades.length; }, 0);
  var totalAUM    = iaDriftAccounts.reduce(function(s,a){ return s + a.aum; }, 0);

  var cards = iaDriftAccounts.length ? iaDriftAccounts.map(function(a) {
    var isHigh    = a.driftScore >= 7;
    var urgLabel  = isHigh ? 'HIGH' : 'MODERATE';
    var cardCls   = isHigh ? 'drift-high' : 'drift-med';
    var badgeCls  = isHigh ? 'high' : 'med';
    var pillCls   = isHigh ? 'high' : 'med';

    var tradeRows = a.rebalanceTrades.map(function(t) {
      var isSell = t.action === 'SELL';
      return '<div class="ia-scan-trade-row">' +
        '<span class="ia-scan-trade-action ' + (isSell ? 'sell' : 'buy') + '">' + t.action + '</span>' +
        '<span class="ia-scan-trade-name">' + t.security + '</span>' +
        '<span class="ia-scan-trade-amt">' + t.amount + '</span>' +
      '</div>';
    }).join('');

    var tradesSection = a.rebalanceTrades.length ?
      '<div class="ia-scan-trades-section">' +
        '<div class="ia-scan-trades-hdr"><i class="fas fa-exchange-alt"></i> Proposed Trades (' + a.rebalanceTrades.length + ')</div>' +
        tradeRows +
      '</div>' : '';

    return '<div class="ia-scan-acct-card ' + cardCls + '">' +
      '<div class="ia-scan-card-top">' +
        '<div class="ia-scan-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
        '<div class="ia-scan-card-info">' +
          '<div class="ia-scan-card-client">' + a.clientName + '</div>' +
          '<div class="ia-scan-card-acct">' + a.accountNum + ' · ' + a.accountType + ' · ' + a.custodian + '</div>' +
          '<div class="ia-scan-card-meta">' +
            '<span><i class="fas fa-coins"></i> ' + a.aumFmt + '</span>' +
            '<span><i class="fas fa-chart-line"></i> ' + a.returnYTDFmt + ' YTD</span>' +
            '<span><i class="fas fa-shield-alt"></i> ' + a.riskProfile + '</span>' +
            '<span><i class="fas fa-exchange-alt"></i> ' + a.rebalanceTrades.length + ' trades needed</span>' +
          '</div>' +
        '</div>' +
        '<div class="ia-scan-card-right">' +
          '<div class="ia-scan-drift-badge ' + badgeCls + '">' + a.driftScore.toFixed(1) + '%</div>' +
          '<div class="ia-scan-urgency-pill ' + pillCls + '">' + urgLabel + ' DRIFT</div>' +
        '</div>' +
      '</div>' +
      tradesSection +
      '<div class="ia-scan-card-footer">' +
        '<button class="ia-scan-footer-btn" onclick="document.getElementById(\'ia-scan-overlay-drift\').remove();iaOpenAccount(\'' + a.id + '\');"><i class="fas fa-eye"></i> View Account</button>' +
        '<button class="ia-scan-footer-btn drift-exec" onclick="event.stopPropagation();iaExecuteRebalance(\'' + a.id + '\');"><i class="fas fa-play-circle"></i> Execute Rebalance</button>' +
      '</div>' +
    '</div>';
  }).join('') :
  '<div class="ia-scan-empty"><i class="fas fa-check-circle"></i><strong>No drift detected</strong>All portfolios are within target allocation thresholds.</div>';

  var html =
    '<div class="ia-scan-overlay" id="ia-scan-overlay-drift" onclick="if(event.target===this)this.remove()">' +
      '<div class="ia-scan-drawer">' +
        '<div class="ia-scan-drawer-header drift">' +
          '<div class="ia-scan-drawer-header-left">' +
            '<div class="ia-scan-drawer-hdr-icon"><i class="fas fa-balance-scale"></i></div>' +
            '<div>' +
              '<div class="ia-scan-drawer-title">Portfolio Drift Monitor <span class="ia-scan-drawer-live">● LIVE</span></div>' +
              '<div class="ia-scan-drawer-sub">Accounts where allocation has drifted &gt;5% from IPS target — AI recommends rebalancing trades</div>' +
            '</div>' +
          '</div>' +
          '<button class="ia-scan-drawer-close" onclick="document.getElementById(\'ia-scan-overlay-drift\').remove()"><i class="fas fa-times"></i></button>' +
        '</div>' +
        '<div class="ia-scan-drawer-body">' +
          '<div class="ia-scan-drawer-summary drift">' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val red">' + iaDriftAccounts.length + '</div><div class="ia-scan-drawer-kpi-lbl">Accounts Drifted</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val orange">' + totalTrades + '</div><div class="ia-scan-drawer-kpi-lbl">Trades Required</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val blue">$' + (totalAUM/1000000).toFixed(2) + 'M</div><div class="ia-scan-drawer-kpi-lbl">AUM Affected</div></div>' +
            (iaDriftAccounts.length ? '<button class="ia-scan-drawer-exec-all drift" onclick="iaExecuteAllRebalances();document.getElementById(\'ia-scan-overlay-drift\').remove();"><i class="fas fa-play-circle"></i> Execute All Rebalances</button>' : '') +
          '</div>' +
          cards +
        '</div>' +
      '</div>' +
    '</div>';

  document.body.insertAdjacentHTML('beforeend', html);
}

function iaCloseDriftPanel() {
  var el = document.getElementById('ia-scan-overlay-drift');
  if (el) el.remove();
}

function iaRenderDriftList() {
  if (!iaDriftAccounts.length) {
    return '<div class="ia-drift-empty"><i class="fas fa-check-circle"></i> No accounts with significant drift detected.</div>';
  }

  var totalTrades = iaDriftAccounts.reduce(function(s,a){ return s + a.rebalanceTrades.length; }, 0);
  var totalAUM    = iaDriftAccounts.reduce(function(s,a){ return s + a.aum; }, 0);

  var summaryBar =
    '<div class="ia-scan-summary-bar">' +
      '<div class="ia-scan-summary-item"><i class="fas fa-exclamation-triangle" style="color:#f59e0b"></i><strong>' + iaDriftAccounts.length + '</strong> accounts need rebalancing</div>' +
      '<div class="ia-scan-summary-item"><i class="fas fa-exchange-alt" style="color:#003087"></i><strong>' + totalTrades + '</strong> trades required</div>' +
      '<div class="ia-scan-summary-item"><i class="fas fa-coins" style="color:#059669"></i><strong>$' + (totalAUM/1000000).toFixed(2) + 'M</strong> AUM affected</div>' +
      '<button class="ia-scan-execute-all-btn" onclick="iaExecuteAllRebalances()"><i class="fas fa-play-circle"></i> Execute All Rebalances</button>' +
    '</div>';

  var cards = iaDriftAccounts.map(function(a) {
    var urgency   = a.driftScore >= 7 ? 'ia-drift-card-high' : 'ia-drift-card-med';
    var urgLabel  = a.driftScore >= 7 ? 'HIGH' : 'MODERATE';
    var urgColor  = a.driftScore >= 7 ? '#dc2626' : '#d97706';
    var driftPct  = Math.min(a.driftScore / 15 * 100, 100);

    var tradeRows = a.rebalanceTrades.map(function(t) {
      var actionCls = t.action === 'SELL' ? 'ia-trade-sell' : 'ia-trade-buy';
      return '<div class="ia-trade-row ' + actionCls + '">' +
        '<span class="ia-trade-action">' + t.action + '</span>' +
        '<span class="ia-trade-security">' + t.security + '</span>' +
        '<span class="ia-trade-amount">' + t.amount + '</span>' +
        '<span class="ia-trade-reason">' + t.reason + '</span>' +
      '</div>';
    }).join('');

    return '<div class="ia-drift-card ' + urgency + '">' +
      '<div class="ia-drift-card-header" onclick="iaOpenAccount(\'' + a.id + '\')" style="cursor:pointer">' +
        '<div class="ia-drift-card-left">' +
          '<div class="ia-drift-gauge-wrap">' +
            '<svg width="64" height="64" viewBox="0 0 64 64">' +
              '<circle cx="32" cy="32" r="26" fill="none" stroke="#e2e8f0" stroke-width="6"/>' +
              '<circle cx="32" cy="32" r="26" fill="none" stroke="' + urgColor + '" stroke-width="6"' +
                ' stroke-dasharray="' + (driftPct * 1.634).toFixed(1) + ' 163.4"' +
                ' stroke-linecap="round" transform="rotate(-90 32 32)"/>' +
              '<text x="32" y="30" text-anchor="middle" font-size="13" font-weight="700" fill="' + urgColor + '">' + a.driftScore.toFixed(1) + '</text>' +
              '<text x="32" y="42" text-anchor="middle" font-size="9" fill="#94a3b8">% DRIFT</text>' +
            '</svg>' +
          '</div>' +
          '<span class="ia-drift-urgency-badge" style="background:' + urgColor + '20;color:' + urgColor + '">' + urgLabel + '</span>' +
        '</div>' +
        '<div class="ia-drift-card-body">' +
          '<div class="ia-drift-card-client">' + a.clientName + '</div>' +
          '<div class="ia-drift-card-acct">' + a.accountNum + ' · ' + a.accountType + ' · ' + a.custodian + '</div>' +
          '<div class="ia-drift-card-meta">' +
            '<span><i class="fas fa-coins"></i> ' + a.aumFmt + ' AUM</span>' +
            '<span><i class="fas fa-chart-line"></i> ' + a.returnYTDFmt + ' YTD</span>' +
            '<span><i class="fas fa-exchange-alt"></i> ' + a.rebalanceTrades.length + ' trades</span>' +
            '<span><i class="fas fa-shield-alt"></i> ' + a.riskProfile + '</span>' +
          '</div>' +
        '</div>' +
        '<div class="ia-drift-card-actions">' +
          '<button class="ia-drift-preview-btn" onclick="event.stopPropagation();iaOpenAccount(\'' + a.id + '\');setTimeout(function(){iaSwitchTab(\'rebalance\',null);},120)"><i class="fas fa-eye"></i> View Plan</button>' +
          '<button class="ia-drift-execute-btn" onclick="event.stopPropagation();iaExecuteRebalance(\'' + a.id + '\')"><i class="fas fa-play-circle"></i> Execute</button>' +
        '</div>' +
      '</div>' +
      (a.rebalanceTrades.length ? '<div class="ia-drift-trades-wrap">' +
        '<div class="ia-drift-trades-hdr"><i class="fas fa-exchange-alt"></i> Proposed Trades</div>' +
        '<div class="ia-drift-trades-header-row"><span>Action</span><span>Security</span><span>Amount</span><span>Reason</span></div>' +
        tradeRows +
        '<div class="ia-drift-trades-footer">' +
          '<button class="ia-drift-card-btn" onclick="iaExportTradeList(\'' + a.id + '\')"><i class="fas fa-file-export"></i> Export Trade List</button>' +
          '<button class="ia-drift-card-btn ia-drift-card-btn-primary" onclick="iaExecuteRebalance(\'' + a.id + '\')"><i class="fas fa-balance-scale"></i> Execute Rebalance</button>' +
        '</div>' +
      '</div>' : '') +
    '</div>';
  }).join('');

  return summaryBar + cards;
}

/* ═══════════════════════════════════════════════════════════════════
   TLH SCANNER PANEL
   ═══════════════════════════════════════════════════════════════════ */
function iaRunTLHScan() {
  var existing = document.getElementById('ia-scan-overlay-tlh');
  if (existing) { existing.remove(); return; }

  var totalSavings = iaTLHAccounts.reduce(function(s,a){ return s + a.tlhOpportunity; }, 0);
  var totalTaxSave = Math.round(totalSavings * 0.35);

  var cards = iaTLHAccounts.length ? iaTLHAccounts.map(function(a) {
    var taxSavings = Math.round(a.tlhOpportunity * 0.35);
    var posRows = a.tlhPositions.map(function(p) {
      var match   = p.match(/^(.+?)\s*\((-\$[\d.]+K)\)$/);
      var posName = match ? match[1] : p;
      var posLoss = match ? match[2] : '—';
      return '<div class="ia-scan-pos-row">' +
        '<span class="ia-scan-pos-name"><i class="fas fa-angle-right"></i> ' + posName + '</span>' +
        '<span class="ia-scan-pos-loss">' + posLoss + '</span>' +
        '<span class="ia-scan-pos-action">Harvest</span>' +
      '</div>';
    }).join('');

    return '<div class="ia-scan-acct-card tlh-card">' +
      '<div class="ia-scan-card-top">' +
        '<div class="ia-scan-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
        '<div class="ia-scan-card-info">' +
          '<div class="ia-scan-card-client">' + a.clientName + '</div>' +
          '<div class="ia-scan-card-acct">' + a.accountNum + ' · ' + a.accountType + '</div>' +
          '<div class="ia-scan-card-meta">' +
            '<span><i class="fas fa-coins"></i> ' + a.aumFmt + ' AUM</span>' +
            '<span><i class="fas fa-shield-alt"></i> ' + a.riskProfile + '</span>' +
            '<span><i class="fas fa-calendar"></i> ' + a.tlhPositions.length + ' position(s)</span>' +
          '</div>' +
        '</div>' +
        '<div class="ia-scan-card-right">' +
          '<div class="ia-scan-tlh-amount">$' + a.tlhOpportunity.toLocaleString() + '</div>' +
          '<div class="ia-scan-tlh-sublbl">gross losses</div>' +
          '<div class="ia-scan-tlh-tax">≈ $' + taxSavings.toLocaleString() + ' tax saved</div>' +
        '</div>' +
      '</div>' +
      '<div class="ia-scan-pos-section">' +
        posRows +
        '<div class="ia-scan-wash-strip"><i class="fas fa-shield-alt"></i> 30-day wash-sale window applied · Replacement securities pre-selected</div>' +
      '</div>' +
      '<div class="ia-scan-card-footer">' +
        '<button class="ia-scan-footer-btn" onclick="document.getElementById(\'ia-scan-overlay-tlh\').remove();iaOpenAccount(\'' + a.id + '\');"><i class="fas fa-external-link-alt"></i> View Account</button>' +
        '<button class="ia-scan-footer-btn tlh-exec" onclick="iaExecuteTLH(\'' + a.id + '\');"><i class="fas fa-leaf"></i> Harvest — $' + a.tlhOpportunity.toLocaleString() + '</button>' +
      '</div>' +
    '</div>';
  }).join('') :
  '<div class="ia-scan-empty"><i class="fas fa-check-circle"></i><strong>No TLH opportunities</strong>No accounts have significant unrealized losses at this time.</div>';

  var html =
    '<div class="ia-scan-overlay" id="ia-scan-overlay-tlh" onclick="if(event.target===this)this.remove()">' +
      '<div class="ia-scan-drawer">' +
        '<div class="ia-scan-drawer-header tlh">' +
          '<div class="ia-scan-drawer-header-left">' +
            '<div class="ia-scan-drawer-hdr-icon"><i class="fas fa-leaf"></i></div>' +
            '<div>' +
              '<div class="ia-scan-drawer-title">Tax-Loss Harvesting Scanner <span class="ia-scan-drawer-live">AI-Powered</span></div>' +
              '<div class="ia-scan-drawer-sub">Unrealized losses that can offset capital gains · 30-day wash-sale rules applied automatically</div>' +
            '</div>' +
          '</div>' +
          '<button class="ia-scan-drawer-close" onclick="document.getElementById(\'ia-scan-overlay-tlh\').remove()"><i class="fas fa-times"></i></button>' +
        '</div>' +
        '<div class="ia-scan-drawer-body">' +
          '<div class="ia-scan-drawer-summary tlh">' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val green">$' + totalSavings.toLocaleString() + '</div><div class="ia-scan-drawer-kpi-lbl">Gross Losses Available</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val blue">$' + totalTaxSave.toLocaleString() + '</div><div class="ia-scan-drawer-kpi-lbl">Est. Tax Savings @ 35%</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val orange">' + iaTLHAccounts.length + '</div><div class="ia-scan-drawer-kpi-lbl">Accounts</div></div>' +
            (iaTLHAccounts.length ? '<button class="ia-scan-drawer-exec-all tlh" onclick="iaExecuteAllTLH();document.getElementById(\'ia-scan-overlay-tlh\').remove();"><i class="fas fa-leaf"></i> Harvest All</button>' : '') +
          '</div>' +
          cards +
        '</div>' +
      '</div>' +
    '</div>';

  document.body.insertAdjacentHTML('beforeend', html);
}

function iaCloseTLHPanel() {
  var el = document.getElementById('ia-scan-overlay-tlh');
  if (el) el.remove();
}

function iaRenderTLHList() {
  var totalSavings = iaTLHAccounts.reduce(function(s, a) { return s + a.tlhOpportunity; }, 0);
  if (!iaTLHAccounts.length) {
    return '<div class="ia-tlh-empty"><i class="fas fa-check-circle"></i> No tax-loss harvesting opportunities identified at this time.</div>';
  }

  var summaryBar =
    '<div class="ia-scan-summary-bar ia-scan-summary-green">' +
      '<div class="ia-scan-summary-item"><i class="fas fa-leaf" style="color:#059669"></i><strong>$' + totalSavings.toLocaleString() + '</strong> total estimated tax savings</div>' +
      '<div class="ia-scan-summary-item"><i class="fas fa-folder-open" style="color:#003087"></i><strong>' + iaTLHAccounts.length + '</strong> accounts with opportunities</div>' +
      '<div class="ia-scan-summary-item"><i class="fas fa-info-circle" style="color:#0891b2"></i>30-day wash-sale rules applied automatically</div>' +
      '<button class="ia-scan-execute-all-btn ia-scan-execute-green" onclick="iaExecuteAllTLH()"><i class="fas fa-leaf"></i> Harvest All</button>' +
    '</div>';

  var cards = iaTLHAccounts.map(function(a) {
    /* estimate after-tax savings at ~35% bracket */
    var taxSavings = Math.round(a.tlhOpportunity * 0.35);
    var posRows = a.tlhPositions.map(function(p) {
      /* parse name and loss from e.g. "INTL Growth Fund (-$4.1K)" */
      var match = p.match(/^(.+?)\s*\((-\$[\d.]+K)\)$/);
      var posName = match ? match[1] : p;
      var posLoss = match ? match[2] : '—';
      return '<div class="ia-tlh-pos-row">' +
        '<span class="ia-tlh-pos-name"><i class="fas fa-angle-right"></i> ' + posName + '</span>' +
        '<span class="ia-tlh-pos-loss">' + posLoss + ' unrealized</span>' +
        '<span class="ia-tlh-pos-action">Harvest</span>' +
      '</div>';
    }).join('');

    return '<div class="ia-tlh-card">' +
      '<div class="ia-tlh-card-header" onclick="iaOpenAccount(\'' + a.id + '\')" style="cursor:pointer">' +
        '<div class="ia-tlh-card-left">' +
          '<div class="ia-tlh-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
          '<div>' +
            '<div class="ia-tlh-card-client">' + a.clientName + '</div>' +
            '<div class="ia-tlh-card-acct">' + a.accountNum + ' · ' + a.accountType + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="ia-tlh-card-right">' +
          '<div class="ia-tlh-savings-big">$' + a.tlhOpportunity.toLocaleString() + '</div>' +
          '<div class="ia-tlh-savings-lbl">gross losses available</div>' +
          '<div class="ia-tlh-tax-est">≈ $' + taxSavings.toLocaleString() + ' after-tax savings @ 35%</div>' +
        '</div>' +
      '</div>' +
      '<div class="ia-tlh-positions-wrap">' +
        '<div class="ia-tlh-pos-hdr"><span>Position</span><span>Unrealized Loss</span><span>Action</span></div>' +
        posRows +
      '</div>' +
      '<div class="ia-tlh-wash-warning"><i class="fas fa-shield-alt"></i> 30-day wash-sale window applied · Replacement securities pre-selected to maintain exposure</div>' +
      '<div class="ia-tlh-card-footer">' +
        '<button class="ia-tlh-detail-btn" onclick="iaOpenAccount(\'' + a.id + '\')"><i class="fas fa-external-link-alt"></i> View Account</button>' +
        '<button class="ia-tlh-card-btn" onclick="iaExecuteTLH(\'' + a.id + '\')"><i class="fas fa-leaf"></i> Execute Harvest for ' + a.clientName.split(' ')[0] + '</button>' +
      '</div>' +
    '</div>';
  }).join('');

  return summaryBar + cards;
}

/* ═══════════════════════════════════════════════════════════════════
   RMD CENTER PANEL
   ═══════════════════════════════════════════════════════════════════ */
function iaOpenRMDCenter() {
  var existing = document.getElementById('ia-scan-overlay-rmd');
  if (existing) { existing.remove(); return; }

  var totalRMD     = iaRMDAccounts.reduce(function(s,a){ return s + a.rmdAmount; }, 0);
  var totalPenalty = Math.round(totalRMD * 0.25);
  var today        = new Date();
  var deadline     = new Date('2026-12-31');
  var daysLeft     = Math.ceil((deadline - today) / (1000 * 60 * 60 * 24));

  var cards = iaRMDAccounts.length ? iaRMDAccounts.map(function(a) {
    var penalty   = Math.round(a.rmdAmount * 0.25);
    var quarterly = Math.round(a.rmdAmount / 4);
    var monthly   = Math.round(a.rmdAmount / 12);
    var pctOfAUM  = a.aum > 0 ? ((a.rmdAmount / a.aum) * 100).toFixed(1) + '%' : '—';

    return '<div class="ia-scan-acct-card rmd-card">' +
      '<div class="ia-scan-card-top">' +
        '<div class="ia-scan-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
        '<div class="ia-scan-card-info">' +
          '<div class="ia-scan-card-client">' + a.clientName + '</div>' +
          '<div class="ia-scan-card-acct">' + a.accountNum + ' · ' + a.accountType + ' · ' + a.aumFmt + ' AUM</div>' +
          '<div class="ia-scan-card-meta">' +
            '<span><i class="fas fa-shield-alt"></i> ' + a.riskProfile + '</span>' +
            '<span><i class="fas fa-percentage"></i> ' + pctOfAUM + ' of AUM</span>' +
            '<span><i class="fas fa-calendar-times"></i> Due: ' + a.rmdDeadline + '</span>' +
          '</div>' +
        '</div>' +
        '<div class="ia-scan-card-right">' +
          '<div class="ia-scan-rmd-amount">$' + a.rmdAmount.toLocaleString() + '</div>' +
          '<div class="ia-scan-tlh-sublbl">required dist.</div>' +
          '<div class="ia-scan-rmd-days"><i class="fas fa-exclamation-triangle"></i> ' + daysLeft + ' days left</div>' +
        '</div>' +
      '</div>' +
      '<div class="ia-scan-rmd-section">' +
        '<div class="ia-scan-rmd-row"><span>IRS Penalty if Missed</span><strong style="color:#dc2626">$' + penalty.toLocaleString() + ' (25%)</strong></div>' +
        '<div class="ia-scan-rmd-row"><span>Quarterly Option</span><strong>$' + quarterly.toLocaleString() + ' / quarter</strong></div>' +
        '<div class="ia-scan-rmd-row"><span>Monthly Option</span><strong>$' + monthly.toLocaleString() + ' / month</strong></div>' +
        '<div class="ia-scan-rmd-row"><span>QCD Option</span><strong>Charitable — up to $105,000 tax-free</strong></div>' +
        '<div class="ia-scan-rmd-penalty-note"><i class="fas fa-gavel"></i> IRS Rule: 25% excise tax on any undistributed amount after Dec 31</div>' +
      '</div>' +
      '<div class="ia-scan-card-footer">' +
        '<button class="ia-scan-footer-btn" onclick="document.getElementById(\'ia-scan-overlay-rmd\').remove();iaOpenAccount(\'' + a.id + '\');"><i class="fas fa-external-link-alt"></i> View Account</button>' +
        '<button class="ia-scan-footer-btn rmd-exec" onclick="iaProcessRMD(\'' + a.id + '\');"><i class="fas fa-paper-plane"></i> Process RMD — $' + a.rmdAmount.toLocaleString() + '</button>' +
      '</div>' +
    '</div>';
  }).join('') :
  '<div class="ia-scan-empty"><i class="fas fa-check-circle"></i><strong>No RMDs Required</strong>No clients have required minimum distributions due for 2026.</div>';

  var irsTable =
    '<div class="ia-rmd-irs-table">' +
      '<div class="ia-rmd-irs-table-hdr"><i class="fas fa-gavel"></i> IRS Uniform Lifetime Table (Reference)</div>' +
      '<div class="ia-rmd-irs-row hdr-row"><span>Age</span><span>Client</span><span>Factor</span><span>2026 RMD</span></div>' +
      iaRMDAccounts.map(function(a, i) {
        var approxAge = 76 + i;
        var factors   = [23.7, 22.9, 22.0, 21.1];
        var factor    = factors[i] || 20.2;
        return '<div class="ia-rmd-irs-row"><span>' + approxAge + '</span><span>' + a.clientName.split(' ')[0] + '</span><span>' + factor + '</span><span style="font-weight:700;color:#d97706">$' + a.rmdAmount.toLocaleString() + '</span></div>';
      }).join('') +
    '</div>';

  var html =
    '<div class="ia-scan-overlay" id="ia-scan-overlay-rmd" onclick="if(event.target===this)this.remove()">' +
      '<div class="ia-scan-drawer">' +
        '<div class="ia-scan-drawer-header rmd">' +
          '<div class="ia-scan-drawer-header-left">' +
            '<div class="ia-scan-drawer-hdr-icon"><i class="fas fa-calendar-check"></i></div>' +
            '<div>' +
              '<div class="ia-scan-drawer-title">Required Minimum Distribution Center</div>' +
              '<div class="ia-scan-drawer-sub">IRS RMD calculations · Deadline Dec 31, 2026 · Penalty: 25% of undistributed amount</div>' +
            '</div>' +
          '</div>' +
          '<button class="ia-scan-drawer-close" onclick="document.getElementById(\'ia-scan-overlay-rmd\').remove()"><i class="fas fa-times"></i></button>' +
        '</div>' +
        '<div class="ia-scan-drawer-body">' +
          '<div class="ia-scan-drawer-summary rmd">' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val orange">$' + (totalRMD/1000).toFixed(1) + 'K</div><div class="ia-scan-drawer-kpi-lbl">Total 2026 RMDs</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val red">$' + (totalPenalty/1000).toFixed(1) + 'K</div><div class="ia-scan-drawer-kpi-lbl">Penalty if Missed</div></div>' +
            '<div class="ia-scan-drawer-kpi-divider"></div>' +
            '<div class="ia-scan-drawer-kpi"><div class="ia-scan-drawer-kpi-val blue">' + daysLeft + '</div><div class="ia-scan-drawer-kpi-lbl">Days Until Deadline</div></div>' +
            (iaRMDAccounts.length ? '<button class="ia-scan-drawer-exec-all rmd" onclick="iaProcessAllRMDs();document.getElementById(\'ia-scan-overlay-rmd\').remove();"><i class="fas fa-paper-plane"></i> Process All RMDs</button>' : '') +
          '</div>' +
          '<div class="ia-rmd-drawer-rule"><i class="fas fa-gavel"></i><strong>IRS Rule:</strong> Clients age 73+ must take RMDs from Traditional IRAs annually. Penalty is 25% of undistributed amount. QCD up to $105,000 allowed as charitable offset.</div>' +
          cards +
          irsTable +
        '</div>' +
      '</div>' +
    '</div>';

  document.body.insertAdjacentHTML('beforeend', html);
}

function iaCloseRMDPanel() {
  var el = document.getElementById('ia-scan-overlay-rmd');
  if (el) el.remove();
}

function iaRenderRMDList() {
  if (!iaRMDAccounts.length) {
    return '<div class="ia-rmd-empty"><i class="fas fa-check-circle"></i> No RMDs required for 2026.</div>';
  }
  var totalRMD  = iaRMDAccounts.reduce(function(s,a) { return s + a.rmdAmount; }, 0);
  var totalPenalty = Math.round(totalRMD * 0.25);
  var today     = new Date('2026-05-14');
  var deadline  = new Date('2026-12-31');
  var daysLeft  = Math.ceil((deadline - today) / (1000 * 60 * 60 * 24));

  /* IRS Uniform Lifetime Table factor for approximate age — simplified */
  var irsTableData = [
    { age: 76, factor: 23.7 },
    { age: 77, factor: 22.9 },
    { age: 78, factor: 22.0 },
    { age: 79, factor: 21.1 }
  ];

  var summaryBar =
    '<div class="ia-rmd-summary-bar">' +
      '<div class="ia-rmd-summary-kpis">' +
        '<div class="ia-rmd-sum-kpi"><div class="ia-rmd-sum-val warn">$' + (totalRMD/1000).toFixed(1) + 'K</div><div class="ia-rmd-sum-lbl">Total 2026 RMDs</div></div>' +
        '<div class="ia-rmd-sum-kpi"><div class="ia-rmd-sum-val red">$' + (totalPenalty/1000).toFixed(1) + 'K</div><div class="ia-rmd-sum-lbl">Penalty if Missed</div></div>' +
        '<div class="ia-rmd-sum-kpi"><div class="ia-rmd-sum-val blue">' + iaRMDAccounts.length + '</div><div class="ia-rmd-sum-lbl">Accounts Due</div></div>' +
        '<div class="ia-rmd-sum-kpi"><div class="ia-rmd-sum-val ' + (daysLeft < 120 ? 'warn' : 'green') + '">' + daysLeft + ' days</div><div class="ia-rmd-sum-lbl">Until Dec 31 Deadline</div></div>' +
      '</div>' +
      '<div class="ia-rmd-summary-rule"><i class="fas fa-gavel"></i> <strong>IRS Rule:</strong> Age 73+ must take RMDs from all Traditional IRAs annually · Penalty: 25% of undistributed amount · QCD up to $105,000 allowed for charitable offset</div>' +
      '<button class="ia-scan-execute-all-btn ia-scan-execute-red" onclick="iaProcessAllRMDs()"><i class="fas fa-paper-plane"></i> Process All RMDs</button>' +
    '</div>';

  var cards = iaRMDAccounts.map(function(a) {
    var penalty    = Math.round(a.rmdAmount * 0.25);
    var monthly    = Math.round(a.rmdAmount / 12);
    var quarterly  = Math.round(a.rmdAmount / 4);
    var pctOfAUM   = a.aum > 0 ? ((a.rmdAmount / a.aum) * 100).toFixed(1) : '—';

    return '<div class="ia-rmd-card">' +
      '<div class="ia-rmd-card-header" onclick="iaOpenAccount(\'' + a.id + '\')" style="cursor:pointer">' +
        '<div class="ia-rmd-card-avatar" style="background:' + a.avatarGrad + '">' + a.initials + '</div>' +
        '<div class="ia-rmd-card-info">' +
          '<div class="ia-rmd-card-client">' + a.clientName + '</div>' +
          '<div class="ia-rmd-card-acct">' + a.accountNum + ' · ' + a.accountType + ' · ' + a.aumFmt + ' AUM</div>' +
          '<div class="ia-rmd-card-tags">' +
            '<span class="ia-rmd-tag ia-rmd-tag-due">RMD Due 2026</span>' +
            '<span class="ia-rmd-tag ia-rmd-tag-pct">' + pctOfAUM + '% of AUM</span>' +
          '</div>' +
        '</div>' +
        '<div class="ia-rmd-card-amount-wrap">' +
          '<div class="ia-rmd-amount-big">$' + a.rmdAmount.toLocaleString() + '</div>' +
          '<div class="ia-rmd-amount-lbl">required distribution</div>' +
        '</div>' +
      '</div>' +

      '<div class="ia-rmd-detail-grid">' +
        '<div class="ia-rmd-detail-row">' +
          '<div class="ia-rmd-detail-item"><span class="ia-rmd-detail-key">Deadline</span><span class="ia-rmd-detail-val warn">' + a.rmdDeadline + '</span></div>' +
          '<div class="ia-rmd-detail-item"><span class="ia-rmd-detail-key">IRS Penalty</span><span class="ia-rmd-detail-val red">$' + penalty.toLocaleString() + ' (25%)</span></div>' +
          '<div class="ia-rmd-detail-item"><span class="ia-rmd-detail-key">Quarterly Option</span><span class="ia-rmd-detail-val">$' + quarterly.toLocaleString() + ' / qtr</span></div>' +
          '<div class="ia-rmd-detail-item"><span class="ia-rmd-detail-key">Monthly Option</span><span class="ia-rmd-detail-val">$' + monthly.toLocaleString() + ' / mo</span></div>' +
        '</div>' +
      '</div>' +

      '<div class="ia-rmd-method-row">' +
        '<div class="ia-rmd-method-label"><i class="fas fa-university"></i> Distribution Method:</div>' +
        '<div class="ia-rmd-method-options">' +
          '<label class="ia-rmd-method-opt ia-rmd-method-selected"><input type="radio" name="rmd-method-' + a.id + '" checked/> ACH to Linked Bank</label>' +
          '<label class="ia-rmd-method-opt"><input type="radio" name="rmd-method-' + a.id + '"/> Check by Mail</label>' +
          '<label class="ia-rmd-method-opt"><input type="radio" name="rmd-method-' + a.id + '"/> QCD to Charity</label>' +
          '<label class="ia-rmd-method-opt"><input type="radio" name="rmd-method-' + a.id + '"/> In-Kind Transfer</label>' +
        '</div>' +
      '</div>' +

      '<div class="ia-rmd-card-footer">' +
        '<button class="ia-rmd-view-btn" onclick="iaOpenAccount(\'' + a.id + '\')"><i class="fas fa-external-link-alt"></i> View Account</button>' +
        '<button class="ia-rmd-card-btn" onclick="iaProcessRMD(\'' + a.id + '\')"><i class="fas fa-paper-plane"></i> Process RMD — $' + a.rmdAmount.toLocaleString() + '</button>' +
      '</div>' +
    '</div>';
  }).join('');

  return summaryBar + cards;
}

