function srRunAllChecks() {
  var btn = event && event.target ? event.target.closest('button') : null;
  if (btn) { btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Running…'; btn.disabled = true; }
  setTimeout(function() {
    if (btn) { btn.innerHTML = '<i class="fas fa-sync"></i> Re-run All Checks'; btn.disabled = false; }
    if (typeof showToast === 'function') showToast('All suitability checks complete — 2 cases need attention', 3000);
  }, 2000);
}

function srApproveCase(id) {
  var c = _srCases.find(function(x) { return x.id === id; });
  var name = c ? c.client : id;
  if (typeof showToast === 'function') {
    showToast('<i class="fas fa-check-shield"></i> Suitability approved for <strong>' + name + '</strong> — proceeding to account funding', 3000);
  } else if (typeof _p5Toast === 'function') {
    _p5Toast('<i class="fas fa-check-shield"></i> Suitability approved for <strong>' + name + '</strong> — proceeding to account funding', 3000);
  } else { alert('Approved: ' + name); }
}

function srRequestDocs(id) {
  var c = _srCases.find(function(x) { return x.id === id; });
  var name = c ? c.client : id;
  if (typeof showToast === 'function') {
    showToast('<i class="fas fa-paper-plane"></i> Document request sent to <strong>' + name + '</strong>', 2500);
  } else if (typeof _p5Toast === 'function') {
    _p5Toast('<i class="fas fa-paper-plane"></i> Document request sent to <strong>' + name + '</strong>', 2500);
  } else { alert('Docs requested: ' + name); }
}

function srOpenFullReview(id) {
  var c = _srCases.find(function(x) { return x.id === id; });
  if (!c) return;
  alert('Full Suitability Review — ' + c.id + '\n\nClient: ' + c.client + '\nRisk Profile: ' + c.riskProfile + '\nScore: ' + c.suitabilityScore + '/100\nDecision: ' + c.aiDecision);
}


