(function() {
  var _origNavAdv = typeof navigateTo === 'function' ? navigateTo : null;
  if (!_origNavAdv) return;
  window.navigateTo = function(page) {
    _origNavAdv(page);
    if (page === 'adv-accounts') {
      requestAnimationFrame(function() { setTimeout(initAdvAccountsPage, 80); });
    }
  };
})();

